window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_015"]={"n":"金朝觐","dyn":"清","poems":[{"t":"登文昌阁","f":"五言绝句","c":["雨后登高阁，春城树色鲜。","流云滋晓润，恰好试新笺。"]},{"t":"送徐栗斋之任义州","f":"七言律诗","c":["拜命陪京令望奢，九重恩诏帝深嘉。","鼎钟旧勒三岑绩，雨露新沾一县花。","化屦何年凫有迹，垂帘尽日鹤排衙。","东风远送旌旗路，为锡龙章荷宠嘉。"]},{"t":"登翠岩山","f":"七言绝句","c":["云山飘渺共低迷，万木青葱入望齐。","直欲举头天外看，红尘隔断数峰西。"]},{"t":"望梳妆楼","f":"七言律诗","c":["栖霞仙子驻龙斿，为近天关筑玉楼。","晓镜开奁初日动，晚妆拂袖暮云流。","目凝淩水波同媚，髻拥虹螺翠共浮。","岩畔苔钱纷五色，遗钿疑是未曾收。"]},{"t":"宿山房","f":"七言绝句","c":["鸡报空林正五更，晓风潇洒六尘清。","山房曾否黄粱熟，梦醒晨钟第一声。"]},{"t":"望笔架山","f":"七言绝句","c":["三丫倚汉峙双双，望若惊人意欲降。","合遣沧溟成墨沈，巨灵擎笔大如杠。"]},{"t":"锦州道上","f":"五言古诗","c":["夙志壮山河，皇舆万象罗。","露华融旭日，海气羃虹螺。","树锁村烟密，花迎鸟语和。","农桑通岛屿，樵牧唱岩阿。","怅别三秋远，愁吟一字多。","殷勤前路去，消息竟如何。"]},{"t":"卢峰口怀古","f":"七言绝句","c":["茂草丰林万壑阴，将军射虎尚雄心。","封侯不遂羞刀笔，饮羽何如饮恨深。"]},{"t":"沙河驿","f":"七言绝句","c":["微雨轻风接轸过，驿亭烟树绕沙河。","连朝渐觉乡音异，来路云山天际多。"]},{"t":"别山戏题","f":"七言绝句","c":["故园别业别离久，别去东风别恨长。","别路感怀牵别绪，别人道出别山阳。"]},{"t":"挽于烈妇即依原韵","f":"七言律诗","c":["哀鸳何事最关心，今忆前言悟后因。","月转蕙帏空对影，鸾飞菱镜自怜身。","百年世事魂犹殢，三月春光梦未真。","无限伤情诗一首，闺中亦有读书人。"]},{"t":"中秋日闱中忆友","f":"五言绝句","c":["忆昔立风檐，搴帘逢好友。","谯楼月二更，令我空回首。"]},{"t":"谒尹文端公墓","f":"五言律诗","c":["相业昭青简，佳城气郁苍。","山灵生肃意，碑纪焕奎光。","一代文章钜，三朝世德彰。","紫荆朝旭日，髣髴在吾乡。"]},{"t":"怀人","f":"七言绝句","c":["咫尺天涯望里春，含情脉脉独伤神。","东风一去无消息，巫峡閒云不恋人。"]},{"t":"望海","f":"七言律诗","c":["海气淩晨炫远眸，洪波无际只平浮。","天涯渺渺难推步，地势茫茫有尽头。","云雨蔚蒸宏润泽，江河归宿混源流。","伊谁不为临崖返，便信蓬莱定可求。"]},{"t":"锦州城南","f":"七言律诗","c":["旧堡新村入望遐，太平风景是田家。","征途络绎通畿辅，农事经营到海涯。","初夏小苗犹待雨，前朝折戟尚沈沙。","堪怜牧竖浑无事，短发垂垂带野花。"]},{"t":"留都","f":"七言律诗","c":["鼎建襄平大业隆，留都犹有旧时宫。","三千化宇风云会，十二重楼烟雨中。","天柱峰峦群拱北，土门江水尽朝东。","太平应绘豳风什，伫待銮舆效祝嵩。"]},{"t":"与孙宝三言海上之胜","f":"五言律诗","c":["有客居南海，寥寥放眼空。","听潮多夜气，长啸起天风。","大泽群流纳，沧波万古同。","请看奔放者，终障百川东。"]},{"t":"次尚铁峰纸鸢元韵 其一","f":"七言绝句","c":["九万鹏程笑楚鸠，扶摇直欲白云游。","天池消息东风便，燕雀相从恨末由。"]},{"t":"次尚铁峰纸鸢元韵 其二","f":"七言绝句","c":["天乐临城听有声，洪钟鲸吼藉风鸣。","调音合向师涓问，休比邻家赵女筝。"]},{"t":"答尚铁峰见访不遇","f":"五言绝句","c":["余本寻春客，君为入幕宾。","当门题午字，谁是会心人。"]},{"t":"瀛洲仙馆文宴","f":"七言律诗","c":["三月春阑近晚和，吟馀恰有客来过。","沈酣书味甘醇醴，飒爽词锋出太阿。","畏友之前浮气少，英年而后世情多。","那堪回首长安道，几向秋风唤奈何。"]},{"t":"偶成","f":"五言绝句","c":["虚堂春昼寂，棋子响丁然。","如有机心在，相争孰后先。"]},{"t":"拟古意","f":"五言绝句","c":["轩厂临风爽，帘疏受月明。","伊人期未至，惆怅不胜情。"]},{"t":"见富厚庵寄内之作戏题","f":"五言绝句","c":["南亩犹勤馌，东郊尚晚春。","如何蚕未老，不见采桑人。"]},{"t":"虞美人花","f":"七言绝句","c":["倚阑䰀鬌坠烟鬟，无奈销魂去不还。","千古无穷垓下恨，朝朝零露泣红颜。"]},{"t":"与书华峰浑河垂钓","f":"古风","c":["浑河滚滚来从东，大木浮出万山中。","水深巨鱼不亲岸，兴波鼓浪吹腥风。","华峰睹此忽技痒，计作长绳约百丈。","屈铁为钩饵以甘，抛向中流试穷想。","昨者筮得贯鱼占，今逢独丝钓鳌詹。","须臾衔索势将去，欲取姑与聊伏潜。","忽闻泼刺转骇绝，鳞甲激扬互明灭。","饥鹰苦羁黄金绦，驽马怒啮白玉埒。","蛟龙失水犹蜿蜒，何况凡鳞出重渊。","力敝已为人所制，目动吻张摇尾怜。","君不见西畔投竿落日边，得鱼盈寸喜忘筌，我得其一抵百千。"]},{"t":"和洪樗庵渡浑河望见沈阳元韵","f":"七言绝句","c":["迢迢深树隐城隅，秋色人家俨画图。","一路檀车徵旧典，几将名胜入清旴。"]},{"t":"寄铁峰书题后一首","f":"五言绝句","c":["寒鸡啼五夜，晓色淡秋河。","一自君归后，阶前落叶多。"]},{"t":"赠朝鲜使臣高二首 其一","f":"五言律诗","c":["惆怅三春别，殷勤此日逢。","作宾偕旅雁，利见卜飞龙。","官纪存遗制，藩篱守旧封。","皇华端不愧，谁解此情钟。"]},{"t":"赠朝鲜使臣高二首 其二","f":"五言律诗","c":["佳气普寰中，人文蔚海东。","休和群沐泽，小大尽从公。","玉帛通王会，衣冠寓古风。","贤劳千里外，珍重此葵衷。"]},{"t":"送李学山一首","f":"七言绝句","c":["秋色櫹椮动客情，一窗晴日数归程。","相知千里何寥落，从事天涯弟与兄。"]},{"t":"赠金清山一首","f":"七言绝句","c":["海邦络绎幸来宾，应识新罗旧有人。","故国不堪回首处，岭南遗绪亦藩臣。"]},{"t":"送朴慈庵二首 其一","f":"七言律诗","c":["神仙何必尽虚无，海外奇方亦不诬。","遂有薪传兼尔雅，多缘仁术重吾儒。","宏开寿宇肱三折，静养慈庵杏五株。","自是为医犹作相，谁从市上觅悬壶。"]},{"t":"送朴慈庵二首 其二","f":"七言律诗","c":["偏因知遇易暌违，鞭影斜阳马上挥。","西土好音成别绪，东医宝鉴嗣前徽。","如君肝胆风尘少，异地关山雨雪霏。","最是离愁医不得，拟将远志寄当归。"]},{"t":"长宁寺迎銮恭纪","f":"五言律诗","c":["糺缦五云红，曈昽映大东。","明昭天日表，肃穆圣神衷。","河岳趋宸跸，旌旗仰下风。","欢声同四野，应彻九重宫。"]},{"t":"恭迎皇上驾幸学宫","f":"七言律诗","c":["□星晓辟正临雍，紫禁鸣銮出九重。","作睹文明皆虎豹，升香典礼属夔龙。","泮芹萦水云霞动，坛杏朝天雨露浓。","欣际岐阳钟鼓化，小臣何幸备趋从。"]},{"t":"大清门谢恩","f":"七言律诗","c":["星月荧辉宫漏鸣，千官济济已朝盈。","遗规丰沛思源本，清奏箫韶和圣明。","翔凤楼前双阙迥，飞龙阁外五云平。","嵩呼应入深宫听，不数流莺绕禁城。"]},{"t":"送洪樗庵回朝鲜","f":"七言律诗","c":["轻云薄雾净长空，邸舍惊心八月中。","客梦醒归黄叶路，秋声吹入绿江风。","行旌指点三湘雁，旅馆清寒四壁虫。","明月不殊乡国异，几回翘首大瀛东。"]},{"t":"送吉凤翔回都二首 其一","f":"五言律诗","c":["客意速归程，寒烟晓月明。","教余时努力，无复问君平。","辽海远无垠，萍踪寄一身。","问君来此地，得友几多人。"]},{"t":"送吉凤翔回都二首 其二 拟游仙体","f":"七言绝句","c":["洞府深沈寂不闻，閒花野草自纷纷。","痴情最是仙家犬，不附青云吠白云。"]},{"t":"留示同人","f":"七言绝句","c":["梅花著色未求工，耐得孤寒质不同。","谁把春光先泄漏，可将消息问东风。"]},{"t":"秋夜旅怀","f":"七言律诗","c":["青灯犹灿五更阑，倚枕孤眠梦未安。","明月自来窗欲晓，秋声何处树号寒。","归心已似飞蓬转，旅况还如落叶单。","起视黄花怜独瘦，霜华昨夜满栏干。"]},{"t":"十二月祗谒祖墓","f":"七言律诗","c":["东山佳气霭重重，远接村庐树色浓。","裕后有资皆世泽，当前何处想音容。","春温秋肃惊霜露，鸟语花香侑鼎钟。","谡谡松声风定后，遗音似祝大夫封。"]},{"t":"咏镜","f":"五言绝句","c":["当面是前因，回头是后身。","总宜明处照，了得本来真。"]},{"t":"宿白旗堡","f":"五言律诗","c":["料峭东风路，残阳柳外斜。","晚烟低野戍，归鸟起平沙。","客梦仍茅店，春冰尚雪花。","劳劳车马地，何事集喧哗。"]},{"t":"渡辽河","f":"七言律诗","c":["莫莫轻寒道阻长，临流马意怯波凉。","冰痕浮涨鱼鳞细，沙碛惊风羊角狂。","川路有情怜过隙，春秋无恙祝高堂。","年来时缅趋庭训，履薄临深矢勿忘。"]},{"t":"无题","f":"七言律诗","c":["高楼深院锁垂杨，曲槛回栏绕洞房。","小住佳人时俏立，偷閒婢子学迷藏。","几回轻燕窥珠箔，漫逐飞花过粉墙。","遗却金钗浑未觉，相携笑语过西廊。"]},{"t":"书院内小斋花草去年所手植也今又重开感而赋之 其一","f":"七言绝句","c":["今年花是去年栽，两度花期两度开。","寒去暑来时物改，年年底事看花来。"]},{"t":"书院内小斋花草去年所手植也今又重开感而赋之 其二","f":"七言绝句","c":["香国迟留方作客，芳园寥落最伤春。","我来恰入东风律，花信犹知识故人。"]},{"t":"书院内小斋花草去年所手植也今又重开感而赋之 其三","f":"七言绝句","c":["掩映东墙接绿阴，重门不启碧苔深。","偷閒只合窥园去，恐负黄花一片心。"]},{"t":"书院内小斋花草去年所手植也今又重开感而赋之 其四","f":"七言绝句","c":["人不怜花花自怜，夙根不断又鲜妍。","花神再度生香意，认取前身结后缘。"]},{"t":"题画","f":"五言绝句","c":["复岭连云暗，孤帆入雾低。","数家烟火处，遥在小桥西。"]},{"t":"次梅澥梦鹤轩夜坐元韵","f":"七言律诗","c":["花天晴爽露华融，斜照残霞落晚红。","乡梦欲归虚夜月，故人相约共清风。","砧寒向晓千家动，桐老惊秋一叶空。","独有诗翁观物妙，尘襟不入太虚中。"]},{"t":"读西域闻见录","f":"七言律诗","c":["信有骚人制作雄，新疆西尽九州同。","皮冠靴屦人伦外，雪海冰山大地中。","险绝难劳槎客访，灵奇未许谢公穷。","总因王气归东土，一任车书万里通。"]},{"t":"文溯阁","f":"五言古诗","c":["星斗焕天章，熙朝制作光。","文昭灵宝瑞，书启酉山藏。","玉检涵蓬观，金题拥墨庄。","沿洄宗圣海，条理总皇纲。","考义详于度，垂谋典以常。","是尊天一阁，能益智千囊。","工轶碑摹篆，劳嗤石作仓。","薪传寻坠绪，逸事极穷荒。","勒鼎功同禹，铭盘志比汤。","留都思溯始，方策示无忘。"]},{"t":"中秋二首 其一","f":"七言律诗","c":["星河淡淡露盈盈，三五秋光月更明。","到处圆灵金镜朗，此身写照玉壶清。","蟾蜍仙府长生药，瓜果人间不夜城。","应是沧溟通桂窟，香风两袖试骑鲸。"]},{"t":"中秋二首 其二","f":"七言律诗","c":["徙倚中庭怯晚寒，为怜今夜月团栾。","蟾光不辨芦花白，镜影还流桂子丹。","诗酒徘徊消客思，风雷倏忽过云端。","嫦娥如许重回首，明远楼前尽可看。"]},{"t":"寄家书有咏","f":"七言绝句","c":["平安惟有一函书，惆怅天涯问视疏。","驿使不来经两月，可知近日复何如。"]},{"t":"次于东浦闻雁元韵","f":"七言律诗","c":["霜信何来动碧林，西风吹雁下寒岑。","远离关塞星初落，秋到潇湘水正深。","应共露盘惊鹤梦，遥怜筝柱写乡心。","遗音欲断衡阳浦，已是更阑玉漏沈。"]},{"t":"秋兴回文","f":"七言律诗","c":["峦翠拖霞淡抹空，远天极望入林枫。","寒山晚去孤云白，落叶秋零半树红。","残简断编修永夜，异乡离梦有清风。","酸心客景烟尘俗，鞍马别途归唳鸿。"]},{"t":"宿李松峰斋中","f":"五言律诗","c":["别馆秋光晚，澄溪绕寺门。","屋连渔火岸，人在水云村。","宿鸟栖钟纽，寒虫咽草根。","谁怜乡国异，俯仰几黄昏。"]},{"t":"题佟松泉小照","f":"五言绝句","c":["松崖悬瀑布，泉眼近云坛。","思得携琴往，同君一再弹。"]},{"t":"读山泉联吟集题后","f":"七言律诗","c":["山籁泉音应感通，遥遥宦旅寄诗筒。","事经艰险翻多韵，思入穷愁愈见工。","形影二人文字里，关山千里梦魂中。","从来博识资名胜，得意文章类史公。"]},{"t":"法帖","f":"七言绝句","c":["是谁新集鲁公书，尺牍珍藏我所无。","伪本竞传多宝塔，此真面目识匡庐。"]},{"t":"古意","f":"五言古诗","c":["皎皎河汉明，迟迟更漏永。","与郎诉相思，恩情成画饼。","郎自有新入，妾自怜孤影。","隔帘见郎来，衿襦强自整。","西闺笑语声，欢乐何驰骋。","视昔犹红颜，未解郎薄倖。","展我罗衣裳，修我红素绠。","夜深语侍儿，无为妾悲哽。"]},{"t":"谢书画七言绝句","f":"七言绝句","c":["喜见华笺翰墨新，标题书画总如神。","幽兰怪石饶清兴，还与诗人自写真。"]},{"t":"怀朝鲜奉使诸公","f":"七言律诗","c":["一别东郊送客镳，鞭丝帽影共飘飖。","剧怜海国相知少，也料萍踪后会遥。","荒馆无人巢旧燕，寒江有路捲归潮。","几回检点留题句，拟向西风再续貂。"]},{"t":"答梦鹤轩主人并呈怀朝鲜使臣诗","f":"七言绝句","c":["秋树寒云望海东，乃心先得我心同。","多惭太上忘情者，真欲临笺问老翁。"]},{"t":"秋郊独步","f":"五言律诗","c":["不道萧森气，秋来只一般。","几多芳草色，剩有旧苔斑。","归鸟下寒树，断云开远山。","终年无寸进，未敢忆刀环。"]},{"t":"过白大将军墓二首 其一","f":"七言绝句","c":["蔓草荒烟墓道横，将军百战气犹生。","白杨响入秋风里，还是雷霆叱咤声。"]},{"t":"过白大将军墓二首 其二","f":"七言绝句","c":["石马临风尚欲嘶，松阴犹似阵云低。","忠魂凛凛黄泉下，遥认灵旗指日西。"]},{"t":"呈梅澥先生二首 其一","f":"七言律诗","c":["世上相知到处新，惟君从不染嚣尘。","定能老去文章壮，不独生平面目真。","与我交情论四载，于人和气属三春。","岂愁鬓发丝丝白，犹是欢娱得顺亲。"]},{"t":"呈梅澥先生二首 其二","f":"七言律诗","c":["风流不歇尚先民，总为文章现化身。","摩诘是诗皆画品，真卿无笔不端人。","储材定许成多士，食俸何须侈万缗。","从此传家兼报国，徽音嗣以石麒麟。"]},{"t":"留别邴西津","f":"七言律诗","c":["一识荆州令望奢，每从甲子数年华。","休教白发雄心少，肯负青云壮志赊。","五夜时勤灯下草，三春定摘榜中花。","前程无限登瀛路，何事谋官上早衙。"]},{"t":"宿永安桥忆郡中诸友 其一","f":"七言绝句","c":["行尽城西卅里程，虹桥西去路纵横。","悲欢昨夜酬诗酒，忍听寒波瑟瑟声。"]},{"t":"宿永安桥忆郡中诸友 其二","f":"七言绝句","c":["三春一梦总朦胧，画壁诗成思未穷。","咫尺天涯何处是，不堪回首暮云东。"]},{"t":"除夕","f":"五言绝句","c":["不见乾坤老，难堪节序更。","谁怜辞旧岁，重似别离情。"]},{"t":"答邴西津书题后即依见赠元韵","f":"七言律诗","c":["东风惠我好诗篇，两地相思心欲然。","不为阳春消别恨，更期景福与文全。","避贤坐接龙门会，指日旋看凤诏宣。","落落竟成平素志，秕糠应笑反居前。"]},{"t":"闻雁二首 其一","f":"五言绝句","c":["犹怯馀寒在，春阴淡欲晴。","东风吹入律，云外两三声。"]},{"t":"闻雁二首 其二","f":"五言绝句","c":["不作悲秋意，关山一路春。","似将消息报，看取再来宾。"]},{"t":"重写诗草偶成七绝一首","f":"七言绝句","c":["果为传诗误大苏，读书便合识之无。","预知往日难回首，留作他年记事珠。"]},{"t":"玉佛","f":"七言律诗","c":["见说西方有圣人，权将玉质奉金身。","幽龛合现庄严相，寰宇常随去住因。","最上菩提归宝觉，无馀灭度豁迷津。","拈花略示如来意，顿悟文心净六尘。"]},{"t":"春晓","f":"七言绝句","c":["春梦醒迟冻欲消，何来深巷卖饧箫。","重帘合趁新晴捲，不禁阳和上柳条。"]},{"t":"春晚","f":"七言绝句","c":["春色迷离向晚看，添衣聊为耐馀寒。","松枝烧入茶铛火，一任轻烟出画栏。"]},{"t":"读西湖志纂二首 其一","f":"七言律诗","c":["想像馀杭风景同，披寻犹在画图中。","可怜富贵延南宋，犹忆神仙说葛翁。","梵宇云深飞鹫岭，层楼水面阚龙宫。","凭他写入丹青笔，输与诗人体物工。"]},{"t":"读西湖志纂二首 其二","f":"七言律诗","c":["林有孤山苏有堤，勾留白傅是湖西。","六桥花雨仍遗迹，十里笙歌半客蹊。","天子时巡筹富庶，才人情思寄标题。","何年得入星槎路，不隔浮云望眼迷。"]},{"t":"春日感怀","f":"七言律诗","c":["坐阅先庚又后庚，风光不觉在清明。","看来锦绣饶三月，恐为诗书误一生。","花鸟依依儿女态，云山渺渺弟兄情。","世人未解因时乐，只向天涯作送迎。"]},{"t":"春日怀梅澥先生用年前见赠元韵二首 其一","f":"七言律诗","c":["共君约略月维三，无限情怀只内含。","芳草思归春未老，晓窗贪睡梦初酣。","偶因空冀曾过北，本为敲诗忆指南。","吟罢小桃红欲绽，却怜花信尚包函。"]},{"t":"春日怀梅澥先生用年前见赠元韵二首 其二","f":"七言律诗","c":["仰正无嫌渎再三，缘知大美在中含。","殷勤隔院酬诗久，相共挑灯听雨酣。","春树萦怀同渭北，折梅逢驿便江南。","遥思桥外藏云处，花屿生机又实函。"]},{"t":"见梅澥先生所绘兰草感怀","f":"五言绝句","c":["芳草入丹青，幽然无伴侣。","临笺细玩之，似共同心语。"]},{"t":"山居杂咏 其一","f":"七言绝句","c":["香篆留烟不捲帘，嘤嘤山鸟唤晴檐。","跫然客屦云深处，知是何人访宋纤。"]},{"t":"山居杂咏 其二","f":"七言绝句","c":["杖藜孤往隔重岚，暖日晴云土意酣。","叱犊冲烟人语处，不知山北与山南。"]},{"t":"山居杂咏 其三","f":"七言绝句","c":["律转东皇焕物华，莺花富贵属谁家。","山中宰相无多事，管得池塘两部蛙。"]},{"t":"山居杂咏 其四","f":"七言绝句","c":["消得风光未了春，多情花鸟最相亲。","无端添入深闺恨，甘作人间薄命人。"]},{"t":"山居杂咏 其五","f":"七言绝句","c":["向晚山云去欲留，何人吹笛写清愁。","试听哀怨如相语，岂是骑牛牧竖流。"]},{"t":"山居杂咏 其六","f":"七言绝句","c":["从容花事去安排，不断生香与物皆。","惟有孤山林处士，却于妻子见高怀。"]},{"t":"山居杂咏 其七","f":"七言绝句","c":["不尽葱青树色深，幽居恰比小禅林。","青山若许榆钱买，肯让祇园布地金。"]},{"t":"山居杂咏 其八","f":"七言绝句","c":["春草生如晤旧知，春风来似慰相思。","杏花开处桃花发，正是劳人小住时。"]},{"t":"清明二首 其一","f":"五言律诗","c":["不隔花村路，酣红上小桃。","鱼争溪涨暖，雁度海风高。","士节甘龙蛰，臣心淡雉膏。","绵山烟漠漠，何处觅蛇号。"]},{"t":"清明二首 其二","f":"五言律诗","c":["是谁甘介节，长揖薄侯封。","白发招偕隐，青山杳旧踪。","禁烟隆报士，寒食不因冬。","纵有绵田奉，难将母氏饔。"]},{"t":"广宁道上忧旱二首 其一","f":"七言律诗","c":["十日征途往复还，翻因苦旱念民艰。","独留夕照明郊甸，尽有晴岚带远山。","芳树笼阴皆暑气，老农挥汗尚愁颜。","谁知霖雨成何日，空望浮云去住閒。"]},{"t":"广宁道上忧旱二首 其二","f":"七言律诗","c":["祈祷封山作雨云，风霾镇日苦炎氛。","曾惊泽国无馀润，合向桑林忆旧闻。","杯酒不消心似醉，燃眉何计志如焚。","功名望已深饥渴，岂似民情待泽殷。"]},{"t":"应乡试西上","f":"七言律诗","c":["几日行程傍海涯，云山回望是吾家。","庭槐近午萦清梦，路柳斜阳带晚霞。","难得临时文入彀，可能到处雨随车。","翻因旱甚思乡土，无复閒情玩物华。"]},{"t":"法王禅林早起二首 其一","f":"七言绝句","c":["梵径深沉少客踪，晓窗睡起揽衣慵。","醒闻清磬香初下，认是阇黎饭后钟。"]},{"t":"法王禅林早起二首 其二","f":"七言绝句","c":["不是禅栖水月邻，齑盐岁月反安贫。","老僧休说斋粮少，我佛原为乞食人。"]},{"t":"丁卯秋试遇蓟州蒋力斋先生于京邸","f":"七言律诗","c":["相士休将冀北空，共君三五月明中。","帘前工谱霓裳曲，云外香飘桂子风。","十载光阴归玉尺，三条烛焰对金虫。","际兹铁树当华日，合报先春到蓟东。"]},{"t":"过十三山口占","f":"五言古诗","c":["北镇临青幽，山尽南山口。","峭茜如列屏，岚光入虚牖。","古洞锁金牛，神物夜出走。","不为五丁驱，粪金日一斗。","岂似田间来，洪縻系人手。"]},{"t":"出都后忆旧二首 其一","f":"七言绝句","c":["千里栖迟客是家，梦魂飞去海天涯。","窗含晓色涵虚白，知是霜华与月华。"]},{"t":"出都后忆旧二首 其二","f":"七言绝句","c":["萍踪泡影与浮沉，情海茫茫入更深。","任是西天称极乐，人间愁苦也惊心。"]},{"t":"挽邴西津二绝 其一","f":"五言绝句","c":["多情不能久，相嘱独遗诗。","谁识长相思，终成古别离。"]},{"t":"挽邴西津二绝 其二","f":"五言绝句","c":["君心何绝决，我意复冥冥。","秋雁天涯去，关山黑复青。"]},{"t":"水仙花","f":"七言律诗","c":["定知仙品不寻常，近得江南异种香。","泉石自甘心共白，缥缃借润甲初黄。","冰肌玉骨差同味，金盏银台欲比芳。","岂似牡丹资沃土，誇称富贵侈称王。"]},{"t":"同沈秀岚月下联句","f":"五言律诗","c":["片月挂银河，流光一掷过。","梦魂乡国异，胸臆宿星罗。","昂首天空碧，挑灯夜啸歌。","游仙寻旧梦，云路莫蹉跎。"]},{"t":"和王义门得子元韵","f":"七言律诗","c":["忆向门高设矢弧，熊罴协梦不曾殊。","韶华再度宜男草，宝气重还合浦珠。","相业三槐得未有，慧心七月识之无。","伫看绕膝随兄后，又著斑衣袭锦襦。"]},{"t":"和沈秀岚春暮回文元韵","f":"古风","c":["濛濛夜露点轻纱，减却愁颜强对花。","红紫遍园春绕梦，碧青涵树暮归鸦。","风光坐里诗同伴，酒意多时客在家。","童竖牧回欢笑语，栊?淡抹一痕斜。"]},{"t":"和沈秀岚咏严子陵钓台元韵","f":"七言绝句","c":["南阳贵士起纵横，江上羊裘尚待清。","忆昔真人台下拜，临流咄咄叹先生。"]},{"t":"和咏孤竹旧里元韵","f":"七言绝句","c":["何事当年扶义起，于心求所安而已。","采薇歌罢渺难寻，山上清风山下水。"]},{"t":"清明纪事兼忆亡友邴西津 其一","f":"七言绝句","c":["铅华零落冷妆台，明月他乡任去来。","曾忆春闺惊梦觉，杜鹃啼处最堪哀。"]},{"t":"清明纪事兼忆亡友邴西津 其二","f":"七言绝句","c":["忆从花县与琴台，回首燕云不复来。","人物已非城郭是，夕阳流水可胜哀。"]},{"t":"清明纪事兼忆亡友邴西津 其三","f":"七言绝句","c":["家山远隔望乡台，曾见家家扫墓来。","酒冷灯昏香缕细，一番消受一番哀。"]},{"t":"清明纪事兼忆亡友邴西津 其四","f":"七言绝句","c":["不生不灭是灵台，不了将来与未来。","总为夙根情重处，怕言哀处却言哀。"]},{"t":"清明纪事兼忆亡友邴西津 其五","f":"七言绝句","c":["怜儿不作望思台，抛却儿家孰再来。","琴鹤未将儿共去，青山相对自生哀。"]},{"t":"清明纪事兼忆亡友邴西津 其六","f":"七言绝句","c":["宿草萋萋绕墓台，一年一度送青来。","黄泉从未春光到，苦雨凄风孰告哀。"]},{"t":"清明纪事兼忆亡友邴西津 其七","f":"七言绝句","c":["风送香魂到夜台，更阑烛尽月明来。","那堪孤雁惊嘹唳，不禁悲声为写哀。"]},{"t":"清明纪事兼忆亡友邴西津 其八","f":"七言绝句","c":["散花天女绕莲台，会见幢幡度世来。","愿到诸天欢喜地，不知人世有离哀。"]},{"t":"和毕续成二首 其一","f":"七言绝句","c":["香绕诗箕一缕魂，依稀幽怨泪添痕。","夜深露重归何处，衰柳残烟锁墓门。"]},{"t":"和毕续成二首 其二","f":"七言绝句","c":["莫论仙才与鬼才，情辞恻恻有馀哀。","却怜诗友归何处，安得寻声一再来。"]},{"t":"送尚铁峰归里二首 其一","f":"七言律诗","c":["春光冉冉落芳菲，龙首山深锁翠微。","廿四条风寻客约，几翻梅雨送君归。","垂杨小院莺儿梦，晴昼疏帘燕子飞。","怎奈临歧回首处，伤心无语独依依。"]},{"t":"送尚铁峰归里二首 其二","f":"七言律诗","c":["世事茫茫少定程，讵今离合限平生。","云驰电掣争消息，海阔天空见性情。","不愿诗才资酒力，应将人品重文名。","殷勤此意谁堪语，昨夜挑灯听雨声。"]},{"t":"将赴长安别梅澥二首 其一","f":"七言绝句","c":["不是嫌春转爱秋，王孙芳草最牵愁。","自怜负债长安道，回首烟光十二楼。"]},{"t":"将赴长安别梅澥二首 其二","f":"七言绝句","c":["梦中乡国意中诗，花满阑干酒满卮。","此景此时谁会得，不堪说与外人知。"]},{"t":"夏云","f":"七言绝句","c":["风拥轮囷絮拥团，晴空惝恍杳无端。","世间万变须臾事，只作浮云到眼看。"]},{"t":"乌拉草三首 其一","f":"七言律诗","c":["草名乌拉古无传，近与村农用最便。","露重芒鞋侵晓去，霜凝葛屦觉春还。","山中踟躅名称异，王不留行义可捐。","几处芊眠平野绿，拟随谢屐到峰巅。"]},{"t":"乌拉草三首 其二","f":"七言律诗","c":["白岳灵葩属贡参，寻常弱草亦堪吟。","生当夏雨宜河畔，捣向秋风入夜砧。","翻笑倾葵空自卫，更如挟纩可人心。","缘随野老同行止，未必跫然喜足音。"]},{"t":"乌拉草三首 其三","f":"七言律诗","c":["地名乌拉又名鞋，兹草称之义转谐。","物产蕃滋仍土俗，春风披拂满江涯。","安排不去尘中驻，冷暖还将足下偕。","试问三千珠履客，可能解屦到当阶。"]},{"t":"拟答乌拉草问即依元韵","f":"七言律诗","c":["观风懒作探花使，辱在刍荛访异材。","冀北群空多骨相，江南春信只梅开。","品题不薄茅檐陋，采取能将卉圃该。","见否何劳重讯问，而今杖策自田来。"]},{"t":"与金黻珽书题后","f":"五言律诗","c":["相忆不相亲，天涯作比邻。","关山萦旅梦，风雨切怀人。","幸有囊中句，羞无席上珍。","何堪知己赠，恐我误青巾。"]},{"t":"僦寓京邸感怀二首寄梅澥书题后 其一","f":"七言绝句","c":["残月衔楼数点星，萦萦乡梦睡初醒。","夜风吹入音声树，误作家山旧雨听。"]},{"t":"僦寓京邸感怀二首寄梅澥书题后 其二","f":"七言绝句","c":["黄金台下又重过，十万人家巨第多。","可惜终南无捷径，长安虽近奈如何。"]},{"t":"寄郑爽斋书题后","f":"七言绝句","c":["小院重门寂寂春，落花拂地静无尘。","可怜双燕如期至，不见年时旧主人。"]},{"t":"立秋","f":"七言绝句","c":["晚树秋蝉最有情，听琴移坐绿阴轻。","漫将昨日薰风曲，谱入商弦作变声。"]},{"t":"十六日出闱后答沈秋岚见寄二首 其一","f":"七言绝句","c":["黄叶西风旧旅情，好将诗语践前盟。","三条烛焰低檐晓，泻作秋岚一色清。"]},{"t":"十六日出闱后答沈秋岚见寄二首 其二","f":"七言绝句","c":["明月怀人惬素心，况当明月共知音。","谁家省识秋思憾，昨夜霓裳一曲吟。"]},{"t":"京邸閒居偶成","f":"五言绝句","c":["征燕去如客，归鸿来作宾。","莫嫌秋已暮，留待小阳春。"]},{"t":"戊辰九月九日举顺天乡试","f":"七言绝句","c":["名场几度看升沈，久困龙蛇起奋心。","今日西风好消息，榜头高处亦登临。"]},{"t":"初十日诣午门谢万寿覃恩恭纪二首 其一","f":"七言律诗","c":["晓望觚棱翠欲流，九重深处五云留。","太平天子登仁寿，习礼诸生近鲁邹。","嵩岳降贤呼万岁，神山筑屋满千筹。","岧峣清禁班联肃，偕引鸿胪过凤楼。"]},{"t":"初十日诣午门谢万寿覃恩恭纪二首 其二","f":"七言律诗","c":["天上蓬壶不计程，秋风得意许骑鲸。","西王母献灵椿瑞，南极星临寿宇平。","礼乐百年涵大化，文章一代属公评。","贤书转愧公车选，行傍宫槐听有声。"]},{"t":"晤熊岳军尉法麟二首 其一","f":"七言律诗","c":["喜是书生立战功，何须地望素崇隆。","毛锥欲扫千军壁，猿臂能开六石弓。","三楚知心思赠剑，一身是胆识丸熊。","珊鞭得意东归去，好著金貂禦朔风。"]},{"t":"晤熊岳军尉法麟二首 其二","f":"七言律诗","c":["入望南天净楚氛，驰驱霜雪旧从军。","每从王事思将父，恰有臣身足报君。","数语论交应白首，十年壮志附青云。","曾经戎马干戈地，不尽酸心吊古文。"]},{"t":"过新甸瞻礼周总镇遗像","f":"五言律诗","c":["所部谁降者，孤城碎欲尘。","将军无战马，孝子不全身。","儿女英雄气，边疆社稷臣。","即今遗像在，挥泪细咨询。"]},{"t":"出闱偶成并简时两峰","f":"七言绝句","c":["京华三月正春深，天气清和乍可心。","我到南宫归未晚，庭槐旬日绿成阴。"]},{"t":"独坐","f":"五言绝句","c":["静境偶忘机，东风入坐衣。","棋残松子落，目送白云飞。"]},{"t":"古意","f":"五言古诗","c":["妾身未惯閒，妾心常相思。","轧轧机杼声，滴滴心中泪。","制锦不成章，织作回文字。"]},{"t":"题赠洪玉峰","f":"七言绝句","c":["欲学长生怯病身，玉峰山外总阳春。","相寻偶到云深处，认是悬壶一老人。"]},{"t":"和答沈秋岚拟古四首 其一","f":"五言古诗","c":["北溟有巨鱼，深居不知处。","长额复修鳞，蛟龙讵敢拒。","吞鳌极四游，跋浪翻蓬屿。","会当雷电章，抟风任遐举。","一出一处间，相去能几许。"]},{"t":"和答沈秋岚拟古四首 其二","f":"五言古诗","c":["君子爱其身，小人爱其财。","富贵偶然事，时乎不再来。","穷愁传著述，发愤郁雄才。","毛锥安可弃，功名薄云台。","昔之先达者，松柏忽已摧。"]},{"t":"和答沈秋岚拟古四首 其三","f":"五言古诗","c":["山川有灵气，钟毓应不虚。","藏器待其时，轗轲诗与书。","刘蕡甘下第，鬻赋耻相如。","若非天下才，谁复嘉子誉。","丈夫会有期，胡乃拘者墟。"]},{"t":"和答沈秋岚拟古四首 其四","f":"五言古诗","c":["二陵佳气多，北望难终极。","秋草被平原，虫语何啾唧。","胜地不久居，佳人难再得。","羡彼双飞鸿，呼群自相识。","相识夫如何，天涯各奋翼。"]},{"t":"恭和御制悯忠诗三十韵","f":"古风","c":["东岳降生发其祥，李公卓荦殊寻常。","读万卷书不爱死，英风侠气偕灵长。","公之少年有大志，斗鸡走狗斥荒唐。","疾恶如仇去如疾，市井无赖呼为狂。","嘉庆戊辰成进士，曲江春宴颇轩昂。","帝曰昌才非百里，汝其试之往江乡。","是年秋涨溢淮泗，鱼鳖斯民走且僵。","诏开内帑赐银币，侵渔牟利相颉颃。","独公力持矫其弊，元凶稔恶王山阳。","杀民更杀慈父母，下同厮仆祸心藏。","岂有酖人羊叔子，叵耐跋扈皆豺狼。","可怜杯酒须臾命，金石毒发摧心肠。","北望宸极魂飞去，月明颜色绕屋梁。","敝袍丹血鬼神护，家人梦寐咸悽怆。","叔父爱侄如爱子，抱衣吞泣心慞惶。","酷暑千里汗相属，披发投地呼天阊。","斯须九重达聪听，赫然震怒天威扬。","白日雷霆惊霹雳，跃跃三尺寒锋铓。","法司传敕急星火，蠢彼群丑失路伥。","楚囚终日相对泣，引颈待罪轵道旁。","剖视心肝血漉漉，腥秽馀沥倾壶觞。","阴风飒飒来格享，松涛怒捲声洋洋。","沈埋冤岳清如洗，昭然依被日月光。","国家论功重死事，丰碑屹立锡天章。","郡君食俸二千石，心如冰玉操如霜。","乃嘱守令为立后，千秋俎豆承馨香。","吁嗟乎书生无气人所鄙，每为斯人意差强。","人生百年忽已矣，谁复言之慨且慷。"]},{"t":"重阳夜宴咏菊影得金字","f":"五言律诗","c":["消遣东篱晚，良宵抵寸金。","黄花须澹泊，绿叶总萧森。","宴近重阳雅，灯然四壁阴。","引觞须尽兴，休负夜游心。"]},{"t":"咏菊影代王从庵作","f":"七言律诗","c":["好是风流处士家，篱边晚课亦生涯。","丛青错落摇书幌，浓绿纷披点绛纱。","几度灯挑思起草，乍惊眼老欲无花。","重阳莫漫愁风雨，明月中天半璧斜。"]},{"t":"咏菊影代李叆川作","f":"七言律诗","c":["绿阴掩映画图新，菊圃昏黄解倦人。","莫惜飞花馀晚节，又从明月认前身。","幽人遁迹原难近，澹友高情恰好亲。","说与丹青浑未解，谁传粉本作殊珍。"]},{"t":"为缪公子新婚戏作","f":"七言律诗","c":["醉耳笙歌不厌频，红镫辉映百花茵。","龙涎香合鸳鸯梦，云母屏开锦绣春。","未识郎情多警怯，应怜妾意惯娇嗔。","鸡声似妒甘同梦，斜月疏星己向晨。"]},{"t":"出留都寄怀诸同志","f":"七言律诗","c":["凉风西下蹴征尘，秋老平芜入望真。","山气空青天欲晓，草根微绿梦回春。","从前虚度犹今我，别后相思又几人。","只为知心深爱惜，难言富贵不如贫。"]},{"t":"闾阳驿晚眺","f":"七言律诗","c":["闾阳古道向幽燕，北镇岧峣耸碧天。","五日行过山一角，九秋旅望月三圆。","园亭寂寞堆残叶，云树苍茫隔暮烟。","老马归途如故识，何须分付著先鞭。"]},{"t":"题赠醉亭主人六首 其一","f":"七言律诗","c":["万壑千岩路转回，寻幽谁向此中来。","山林客气偕仙侣，弧矢家风毓将才。","圣世桑麻行处有，公门桃李旧时栽。","未容尘迹通蹊径，曾否云关为我开。"]},{"t":"题赠醉亭主人六首 其二","f":"七言律诗","c":["主人揽胜启园亭，领取春光户不扃。","杖履高风堪自许，家山旧雨且重听。","云窗日暖涵波碧，茶灶烟微带柳青。","共道清明看更好，输他前此未曾经。"]},{"t":"题赠醉亭主人六首 其三","f":"七言律诗","c":["昔传海上有蓬壶，缥缈仙乡望欲无。","绿野归田馀晚计，青山隐几足清娱。","千重树色含虚牖，万变云容拥画图。","为看长途车马客，萧然吾亦爱吾庐。"]},{"t":"题赠醉亭主人六首 其四","f":"七言律诗","c":["一脉清泉入短墙，曲缘花径引流觞。","村醪熟酿莼鲈美，山雨初过枣栗香。","白发逢秋须健饭，黄花虽晚不忧霜。","扶筇且立溪桥畔，露冷葭苍水一方。"]},{"t":"题赠醉亭主人六首 其五","f":"七言律诗","c":["野草寒枯计禦冬，垂帘未捲出门慵。","椒兰绕座融金鸭，鳞甲飞空起玉龙。","解识天心梅数点，閒消世虑酒千钟。","请君曝背南窗下，莫道阳和不可逢。"]},{"t":"题赠醉亭主人六首 其六","f":"七言律诗","c":["千金一诺两怀思，二十年前话别时。","亭榭今犹依旧主，须眉端不愧男儿。","空山流水传情绪，满目飞花尽酒卮。","近识閒愁无处著，只推我醉未曾知。"]},{"t":"在盛京恭逢万寿圣节遥忆都中前辈诸公躬与盛典恭纪","f":"七言律诗","c":["无疆圣节值良晨，先已恩覃草莽臣。","葵藿有心惟向日，松云生意自长春。","南山祝寿归周雅，东国称觥近古豳。","万里君门西望处，却怜蜗角属何因。"]},{"t":"元旦立春","f":"五言律诗","c":["昨日除残腊，今朝报早春。","体元归圣主，迎岁在寅宾。","北陆回阳驭，东风拥化轮。","椒花初献瑞，何惜酒千巡。"]},{"t":"题苏东坡游赤壁图","f":"七言绝句","c":["当年横槊亦风流，蔽日旌旗一炬休。","樽酒空山明月夜，何人高赋大江秋。"]},{"t":"题苏武牧羊图","f":"七言绝句","c":["十九年来一旅臣，南朝谁念牧羊人。","凝霜裂指犹持节，难与胡儿道苦辛。"]},{"t":"示学中诸同志","f":"七言律诗","c":["山绕孤村树绕庐，依稀风景似鹅湖。","关头猛省登先岸，弹指流光逝隙驹。","觉路还须庸玉汝，官阶何必执金吾。","古来憎命文章甚，不信知心一世无。"]},{"t":"春日怀沈阳诸友人拟古一首","f":"五言古诗","c":["西山当户牖，飒然来清风。","阴阳互新故，茂兰发幽丛。","采之欲盈把，将以寄邮筒。","故人一为别，远在闾山东。","思君不可见，怀君何有穷。","白云自卷舒，目送双飞鸿。","延伫独无语，我心复忡忡。"]},{"t":"清明一首","f":"五言律诗","c":["清明春未暮，偕乐及同群。","绿变榆槐火，青归竹木云。","小儿循造化，野马入氤氛。","谁念绵山上，千秋义士坟。"]},{"t":"初夏偶成","f":"五言律诗","c":["见说农家好，书声共绩声。","君恩宽负担，天意适阴晴。","花丽春光艳，诗和躁气平。","长安多少路，犹忆重行行。"]},{"t":"壮士行","f":"七言古诗","c":["雄风表海称洋洋，古冶神勇如鹰扬。","忆昔从君下三晋，横矛倒戟何轩昂。","君之爱马玉花骢，萧萧长嘶如追风。","回望临淄绝尘去，咫尺已与黄河通。","深渊大泽神护呵，中有怪物为妖鼍。","翻风鼓浪来酣战，斯须骏马沈洪波。","小大从公肝胆裂，勇士忿怒下妖穴。","英风侠气贯长虹，瞥惊匕首飞霜雪。","暗恶叱咤惊蛟龙，红涛一缕翻污血。","吾闻忠信涉悬流，投璧斩蛟孰为俦。","将军英勇气盖世，躯命胡为二桃休。"]},{"t":"春日闻雁七言绝","f":"七言绝句","c":["又向平沙结阵过，江南消息近如何。","人间惯听莺儿语，只为秋声寄感多。"]},{"t":"登翠岩山七言绝","f":"七言绝句","c":["孤峰直上白云隈，涧底青松荫碧苔。","我是夙缘应到此，当年曾否谢公来。"]},{"t":"题画狮子","f":"古风","c":["我读西山经，见闻难议拟。","云有百兽王，奇质乃俶诡。","山鸣谷应生长风，搏象易如搏鼠伎。","伏者不噬强者拒，称仁何独称麟趾。","只恐破壁吼一声，斯须奋发去千里。"]},{"t":"题双鹊春梅图七言绝","f":"七言绝句","c":["春光怜物去犹迟，满树琼华未落时。","他日檐前传好信，此身原在最高枝。"]},{"t":"春日登北山望塞外诸峰","f":"七言绝句","c":["西北云山控紫台，望中野马息尘埃。","莫嫌邱垤无风景，应是昆崙一脉来。"]},{"t":"辛未捷南宫","f":"七言绝句","c":["棘院墙阴听唱名，飞传笺纸满都城。","忽闻我亦泥金报，竟似嘉宾倒屣迎。"]},{"t":"四月二十三日保和殿策试","f":"七言律诗","c":["英雄难尽网罗收，聊藉文章作应求。","五色卿云谁载笔，九重清禁孰前筹。","花因向日无凡艳，水到朝宗少细流。","亦识山林佳趣永，春风曷似凤池头。"]},{"t":"归里吟","f":"七言律诗","c":["宽閒负担爱山林，同是君王造就深。","鞅掌未谙他日事，读书讵负少年心。","慈恩塔影云间矗，长乐钟声梦里寻。","依旧芸窗公案在，春风秋月助清吟。"]},{"t":"抵里后寄留都诸同志","f":"七言律诗","c":["微雨莺声御柳新，飞花流水曲江春。","君王许作归田计，文字难为造福神。","东国怀思空近日，北堂称寿慰慈亲。","大罗天上分明在，一觉游仙梦未真。"]},{"t":"蠹鱼吟","f":"七言古诗","c":["蠹鱼力破万千卷，幻身脉望人未知。","仙窟已逢三度劫，绵绵化为长命丝。","芸香佩服莫相避，其如臭味无差池。","盘屈偃伏似龙蛰，夜深太乙来下窥。","驱使丁甲穿壁去，砚池涓滴甘霖施。"]},{"t":"寄缪梅澥二首 其一","f":"七言律诗","c":["主人爱我累千觞，赠我珍珠字数行。","相剑不逢雷焕子，弹琴谁遇蔡中郎。","中年哀乐频搔首，往日莺花只断肠。","聊为鸡声一兴舞，晨星三五在东方。"]},{"t":"寄缪梅澥二首 其二","f":"七言律诗","c":["疏慵无计遣韶光，饮酒游山学孟阳。","得意逢场皆露电，生来憎命岂文章。","笔刀制锦能藏拙，风剪裁春半属狂。","惹起深闺穷女恨，嫁衣终日为谁忙。"]},{"t":"望雨诗一首口占","f":"五言绝句","c":["风急云还散，风柔云复微。","老天须作合，也自有暌违。"]},{"t":"和难妇诗即依元韵","f":"七言律诗","c":["卢家少妇近如何，只恐无愁愁复磨。","羽檄传来丹凤阙，烽烟直上白云窝。","露行春陌惊魂渺，草没荒城战骨多。","安得木兰同夥伴，偕归一拭泪痕沱。"]},{"t":"冬夜怀梅澥一首","f":"七言律诗","c":["思情款款复绵绵，又向西风写寸笺。","此际此情深夜月，为寒为暖小阳天。","都无可忆从前事，尽有相逢未了缘。","知感生平能有几，于今不见已三年。"]},{"t":"悼马生亡父一首","f":"五言律诗","c":["年少功未就，况当失所天。","遗言无一语，观行重三年。","乌鸟啼残粒，乔林起暮烟。","堪怜马氏子，应有白眉贤。"]},{"t":"咏史","f":"五言古诗","c":["孔孟若元气，浑然天地间。","风雷不改色，草木皆新鲜。","大含入无间，钻仰高且坚。","自古生未有，称谥胡称宣。","子舆本非字，何况指名焉。","荀扬与墨翟，其又焉能贤。"]},{"t":"赠别马锡侯秉銮一首","f":"五言律诗","c":["与我初相识，于今二十年。","诗书绵世泽，衣钵愧真传。","此际挑镫夜，当时立雪天。","离怀共樽酒，无计托瑶笺。"]},{"t":"怀石绮园二首 其一","f":"五言古诗","c":["我爱石绮园，读书无专门。","文章与法律，一一窥本原。","男儿志康济，安用糟粕言。","大才用之小，劳此案牍繁。","我闻古良吏，所治无覆盆。","又闻古遗直，其民自不冤。","犴狴少留狱，鸡犬无惊魂。","臣门纷如市，镇日来者喧。","臣心净如水，挠之终不浑。","古人如可作，安能世俗论。","诗书有馀泽，政举人乃存。","君情高且洁，冰雪欲无痕。","君志远且大，势欲江海吞。","暂滞鸿泥爪，终当淩风骞。"]},{"t":"怀石绮园二首 其二","f":"五言古诗","c":["我憾石绮园，轻财如粪土。","千金虽易来，一钱亦足数。","我有白练衫，上书兰亭谱。","剪灯恣夜谈，翻被膏油腐。","绮园绐我方，云曾考之古。","渗以金屑霏，快如披云睹。","漆为蟹壳销，针向磁石取。","物理有同然，何必出撰杜。","余心是其言，攻错借圜府。","初如大冶金，跃跃还起舞。","又如铸莫邪，一鼓复再鼓。","可怜孔方兄，无罪膏吾斧。","讵知堕术中，夫人乃自侮。","吾今索债来，还须言阿堵。"]},{"t":"题老子传经图一首","f":"七言律诗","c":["君历周朝定几秋，生来白发已盈头。","五千道德丹经秘，百二函关紫气留。","也共尼山同载笔，今番海屋又添筹。","青牛花外归何处，昨见天河饮上流。"]},{"t":"题渊明种菊图一首","f":"五言律诗","c":["先生有高趣，招隐为黄花。","北牖羲皇古，东篱岁月赊。","桃源真福地，彭泽岂吾家。","何事陶宏景，空排宰相衙。"]},{"t":"题葛仙饭蜂图一首","f":"古风","c":["庄生化蝴蝶，幻身不自知。","葛翁作蜂子，吐哺惊且疑。","想公之口甘如蜜，出尔反尔纷烦滋。","世人吃饭脊梁过，安能糟粕出神奇。","呜乎谪仙咳唾九天外，纵有珠玉不疗饥。"]},{"t":"题子陵垂钓图一首","f":"七言绝句","c":["富春高尚傲王侯，鲈鲤西风一敝裘。","偏是贵交徵不起，客星孤照大江头。"]},{"t":"题太白醉月图一首","f":"古风","c":["乐哉学士，对月称觞。","此身此影，共此清光。","臣有仙骨，谪居醉乡。","清平雅奏，春宴沈香。","气吞力士，眼识汾阳。","举首凝望，夜色如霜。","峨嵋西度，流照夜郎。"]},{"t":"题伯牙访友图一首","f":"五言古诗","c":["吾师在海上，风涛万顷深。","吾友在山中，樵径作微吟。","高山有清韵，流水无竞心。","孤往兴未己，呼僮囊素琴。","宁辞一再鼓，会须有知音。"]},{"t":"乙亥九月九日纪事诗四首 其一","f":"七言律诗","c":["回首流光十五年，千金一刻总徒然。","当时无故谁知乐，弥月多菑更可怜。","今日乍醒前日梦，他生难必此生缘。","啿嗟不幸遭阳九，惊雁离群叫暮天。"]},{"t":"乙亥九月九日纪事诗四首 其二","f":"七言律诗","c":["荆树西风力不支，那堪弱弟此长辞。","怜兄念切将身代，思母情深数发悲。","零落衣裳成往迹，抛残笔墨付伊谁。","伤心问字殷勤日，忽忽生平有几时。"]},{"t":"乙亥九月九日纪事诗四首 其三","f":"七言律诗","c":["秋风落叶感星霜，辜负韶光春梦长。","砚北随兄供笔墨，厨东呼嫂问羹汤。","劫当桓景都归命，礼据檀弓可勿殇。","他日登高临眺处，天涯布奠一倾觞。"]},{"t":"乙亥九月九日纪事诗四首 其四","f":"楚辞体","c":["花萼惊风尽此番，已看秋色老椿萱。","空将无死嗟予季，多为尊师谓我昆。","长逝魂兮安所适，生来命也复何言。","从前书画擎双管，化作虬松拱墓门。"]},{"t":"感遇","f":"七言律诗","c":["清福神仙望已休，家山郁郁此勾留。","文章岂为求知己，兄弟无缘共宦游。","往日名途堪屈指，中年人事费持筹。","不愁静里难消遣，每遇寻春到陌头。"]},{"t":"答张少亭二首 其一","f":"七言绝句","c":["南国山川旧有灵，精华上诉老人星。","近来垂照芸窗下，不数燃藜太乙青。"]},{"t":"答张少亭二首 其二","f":"七言绝句","c":["老去湖山兴未阑，金陵王气付江干。","何当载酒龙盘里，同倚栏杆看牡丹。"]},{"t":"为梅澥题扇蓄以殉葬","f":"五言律诗","c":["诗有同声和，人皆雅量宜。","共兹三不朽，结作两相思。","华表仍归鹤，兰亭欲附椑。","春蚕虽已老，犹自有馀丝。"]},{"t":"丙子初春喜晤梅澥先生因怀尚铁峰沈秀岚适先生以诗钞见示率成长歌用为题词","f":"五言古诗","c":["少与公相识，长从公相游。","蒙公青眼待，不与下士俦。","我乃不揣陋，公乃为包羞。","别公六期岁，白发已盈头。","昔公宦游日，东南人士稠。","观水既观海，复不绝泡沤。","登山既登岱，复不小阜邱。","冰鉴期无爽，霜毫时秘抽。","鹤子秋风健，兰孙春气柔。","黄金散不尽，终可补箕裘。","积书千万卷，琅嬛宝笈留。","晚年自订稿，呼我为编修。","八万五千字，一一皆清遒。","将为纪年谱，将为咨事诹。","天资既纯粹，高识乃不侔。","向当共知己，来自山海陬。","银冈尚北望，锦水须东流。","独有松江客，溯洄难遽求。","人事类如此，我心徒悠悠。","与公期不朽，魂梦各千秋。"]},{"t":"游普陀山寺一首","f":"七言律诗","c":["普陀山外湿云流，马上经行取径幽。","梵宇飞空攒宝树，灵湫不泄守潜虬。","度生谁出三千界，回首重来廿四秋。","半日偷閒聊共适，老僧酬应未曾休。"]},{"t":"同张少亭看牡丹口占","f":"五言绝句","c":["野菊寒篱下，幽兰傍泽隈。","牡丹生富贵，还许待春来。"]},{"t":"游小洞山寺口占","f":"五言律诗","c":["非梦忽疑梦，惊心转自猜。","入山寻故径，隔树识莲台。","危石如累卵，依然次第排。","缘何初到者，不异旧曾来。"]},{"t":"何云从萧殿臣二戚谊招饮一首","f":"七言律诗","c":["难得嘉名似太真，风流不减洛川神。","红妆引烛三更艳，白雪飞声四座春。","薄命未知团扇恨，芳年正值破瓜辰。","因他面傅何郎粉，又恐萧郎是路人。"]},{"t":"落花二首 其一","f":"七言律诗","c":["尽教清昼自舒长，争奈春光费较量。","暖日迟迟多已去，东风故故亦堪伤。","小桥柳絮全铺径，别院桐阴半拂墙。","况是夜来风雨过，何堪扫地尽文章。"]},{"t":"落花二首 其二","f":"七言律诗","c":["蓬蓬生计满天涯，觉得春深是落花。","香色渐于浓处减，光阴不觉去时奢。","何堪倦蝶醒残梦，尽有閒蜂上旧衙。","生灭自来还造化，休将情妒怨封家。"]},{"t":"元旦一首","f":"五言律诗","c":["造化无停息，乘除改岁年。","东风先入律，星纪又周天。","爆竹宣阳气，椒花启寿筵。","北堂春正永，槐荫满庭前。"]},{"t":"梅澥先生赠垂丝柳一枝种之成阴矣承先生邮函相讯作此以答","f":"五言律诗","c":["自得先生柳，栽培向小园。","分条宁计尺，扶干恰当门。","腰减春风力，眉销故国魂。","长丝空缕缕，别恨与谁论。"]},{"t":"丁丑举一子为亡弟盈出继","f":"五言律诗","c":["庭前荆树夥，荣落两暌违。","既得亲枝共，宁虞奕叶微。","痴情天不厌，异举众相非。","赖有贤妻子，绵绵永绍衣。"]},{"t":"柳眠一首","f":"七言绝句","c":["新丝缕缕倩风柔，情态三眠倦欲休。","千百流莺呼不起，怕醒春梦又添愁。"]},{"t":"莺梭","f":"五言绝句","c":["三月花如绣，制锦须金梭。","柳丝织未了，又添雨丝多。"]},{"t":"帘波二首 其一","f":"五言绝句","c":["竹簟生微凉，北窗卧不起。","呼僮下筠帘，犹带湘江水。"]},{"t":"帘波二首 其二","f":"五言绝句","c":["帘箔何空明，差胜侧理纸。","只愁燕误飞，剪取西江水。"]},{"t":"镜花二首 其一","f":"五言绝句","c":["美人晓簪花，蛾眉懒不画。","有色不闻香，终是虚花界。"]},{"t":"镜花二首 其二","f":"五言绝句","c":["名花遇倾国，自古两相欢。","今在明镜里，权作美人看。"]},{"t":"烛影一首","f":"五言绝句","c":["兰膏吐青燄，知是夜眠迟。","独有摇红处，千秋不释疑。"]},{"t":"书蠹二首 其一","f":"五言绝句","c":["食古须能化，饮香年复年。","蠹书不蠹国，何愧守残编。"]},{"t":"书蠹二首 其二","f":"五言绝句","c":["诗书本不腐，何自有虫生。","力能破万卷，厥罪比秦坑。"]},{"t":"笔架山四首 其一","f":"七言绝句","c":["卓笔峰高不可求，临池空自意悠悠。","此中本有珊瑚架，铁网何须屡溯游。"]},{"t":"笔架山四首 其二","f":"七言绝句","c":["三峰突起宛中央，应是徐陵搁笔场。","试问古来谁巨手，韩潮苏海阅沧桑。"]},{"t":"笔架山四首 其三","f":"七言绝句","c":["大笔如杠只此支，谁将巨手一重持。","风帆海上朝朝过，疑是杨花入砚池。"]},{"t":"笔架山四首 其四","f":"七言绝句","c":["谁是元虚作赋才，文章定可到蓬莱。","应知此后难提笔，故放文澜捲浪来。"]},{"t":"依梅澥先生题扇元韵奉和","f":"七言律诗","c":["每愧庸庸被奖旌，相逢心许若平生。","风吹野草鸣宾鹿，春满乔林度小莺。","讲艺自能消客气，忘形更复重交情。","骊歌写作绳头字，犹幸年来老眼明。"]},{"t":"怀梅澥二首 其一","f":"七言律诗","c":["往事依依幻亦真，分明笺字墨华新。","离筵曾照西楼月，别赋空怀南浦春。","万卷难谙天下事，百年老去眼中人。","辞君再晤知何日，沧海浮萍寄此身。"]},{"t":"怀梅澥二首 其二","f":"七言律诗","c":["柳丝鞭影度春城，又听西风落叶声。","老鹤栖阴传远韵，绿云萦榻发幽情。","想因知已劳相思，也恐耽吟碍养生。","何似含饴弄孙乐，馀年赢得一身轻。"]},{"t":"怀李公师惠","f":"五言律诗","c":["李公敦夙好，生死见交情。","谁识扶棺痛，深于负笈诚。","燕云悲客路，淩水咽归程。","不为呼将伯，奚从旅榇行。"]},{"t":"奉和洪玉亭送别元韵四首 其一","f":"七言绝句","c":["津柳依依最可怜，葛衣宽褪又添绵。","与君判袂西风里，从此参商定几年。"]},{"t":"奉和洪玉亭送别元韵四首 其二","f":"七言绝句","c":["频挑烛泪夜阑时，咫尺天涯未忍离。","我自不辞心曲乱，伊人空复念温其。"]},{"t":"奉和洪玉亭送别元韵四首 其三","f":"七言绝句","c":["骊驹就道竞相誇，迎送青山到处家。","忽忆迩来耽习静，也因离索厌繁华。"]},{"t":"奉和洪玉亭送别元韵四首 其四","f":"七言绝句","c":["海雨江风满客襟，片帆难搁故乡心。","预知此后相思苦，总以长年度寸阴。"]},{"t":"有感","f":"七言律诗","c":["自笑雕虫误半生，虚名何益竟何成。","韶年碌碌空回首，后事茫茫少定衡。","命本难知姑进取，人能悔过是聪明。","迩因悟得南华意，纯以天机自在行。"]},{"t":"题孙墨林小照一首","f":"五言律诗","c":["南国多佳士，风流孰若君。","持筹无市气，展卷挹清芬。","锦水浮归棹，吴江冷暮云。","精神千古在，元鹤与同群。"]},{"t":"送伊莘起主事任满赴都一首","f":"七言律诗","c":["三辅分猷马首东，京华回望五云中。","黍苗润借随车雨，钱谷清馀两袖风。","愧我疏慵闻诲少，知君廉静与人忠。","何缘芳草思归早，依旧春光迥不同。"]},{"t":"梅澥所赠柳春日复萌书此寄怀","f":"七言律诗","c":["垂丝袅袅拂风轻，犹忆殷勤唱渭城。","当户可容栖小隐，眠春无计遣流莺。","黄金有色初分种，青眼看人感旧盟。","树尚如斯何况我，三年拱把讵无情。"]},{"t":"和答同年何愚溪都中见怀元韵二首 其一","f":"七言律诗","c":["长安西望暮天高，暂憩閒身跋涉劳。","此日怀君临素简，当时怜我赠缔袍。","五年延阁迟鸿羽，十载恩荣毓凤毛。","谁识山窗风雨夜，几回惊起听松涛。"]},{"t":"和答同年何愚溪都中见怀元韵二首 其二","f":"七言律诗","c":["几番夏暑与冬寒，笔墨分明一晤难。","五月莺花边地景，九秋风雨海门观。","省中兰蕙新沾露，柳外溪桥共倚栏。","春满上林万年树，何时分借一枝安。"]},{"t":"塞上吟二首 其一","f":"七言律诗","c":["九龙山控小淩川，朔气凝寒欲暮天。","设险重关勤远戍，戒严三卫想当年。","华风渐被通蕃汉，文教流传孰后先。","总为太平安土乐，人家多半是屯田。"]},{"t":"塞上吟二首 其二","f":"七言律诗","c":["我今来此又隆冬，极目斜阳簇乱峰。","松岭设关分界限，淩川入塞识朝宗。","边防将吏兼司税，土著兵民久务农。","一带疏林成列处，当年细柳想军容。"]},{"t":"课农七首 其一","f":"七言绝句","c":["田连阡陌亩南东，锄雨耕云处处同。","只为相驯欢笑语，翕然绘出太平风。"]},{"t":"课农七首 其二","f":"七言绝句","c":["时当春季识农忙，笠影婆娑趁夕阳。","偏是老人知岁稔，占晴占雨半荒唐。"]},{"t":"课农七首 其三","f":"七言绝句","c":["昨夜沾濡雨一犁，春融袯襫又涂泥。","朝来试向东郊望，人迹依稀遍晓堤。"]},{"t":"课农七首 其四","f":"七言绝句","c":["曾从郊外去迎春，又看东皋播种人。","虽际太平农事乐，谁知颗粒总艰辛。"]},{"t":"课农七首 其五","f":"七言绝句","c":["好是和风旭日时，分明画出大田诗。","愿将粉本陈丹陛，当日豳风想见之。"]},{"t":"课农七首 其六","f":"七言绝句","c":["三春休说日迟迟，有鸟催耕恐失时。","欲报西成且东作，农歌半是赛神诗。"]},{"t":"课农七首 其七","f":"七言绝句","c":["每从耕凿识民情，依恋家山课雨晴。","他日长安西望处，可能回首忆躬耕。"]},{"t":"李将军射虎石二首 其一","f":"七言绝句","c":["老将威名震北平，却教顽石落魂惊。","笑他试剑原儿戏，未必吟成猛虎行。"]},{"t":"李将军射虎石二首 其二","f":"五言绝句","c":["力如虎尤猛，心比石还坚。","以此威弧矢，何愁不应弦。"]},{"t":"吴越王铁弩射潮","f":"七言律诗","c":["三千弓弩越人弯，竟使蛟龙退舍还。","聊藉威灵降水国，犹看潮势荡湖山。","石桥渡海能鞭血，铜柱封疆可限蛮。","当日既知安境界，何缘此后复为患。"]},{"t":"读吊古战场文四首 其一","f":"七言绝句","c":["万骑连营催暮笳，思归军士死为家。","沙场万里埋枯骨，哭奠徒劳天一涯。"]},{"t":"读吊古战场文四首 其二","f":"七言绝句","c":["雪满征途远帝阍，金戈铁马若云屯。","成功也有生归日，寝寐犹惊未定魂。"]},{"t":"读吊古战场文四首 其三","f":"七言绝句","c":["黄沙白草望中迷，新鬼含愁旧鬼悽。","一样北邙山下死，堪怜塞北与辽西。"]},{"t":"读吊古战场文四首 其四","f":"七言绝句","c":["我欲开编吊古人，何堪卒读耐酸辛。","书生未识从征苦，犹说文章薄武臣。"]},{"t":"李愬雪夜入蔡州四首 其一","f":"七言绝句","c":["雪夜衔枚走敌师，军声鹅鹳两惊疑。","探囊取得吴元济，计夺昆崙一觉时。"]},{"t":"李愬雪夜入蔡州四首 其二","f":"七言绝句","c":["六出都缘兆岁丰，能邀天倖是元戎。","休誇谋定由裴度，此夜应推滕六功。"]},{"t":"李愬雪夜入蔡州四首 其三","f":"七言绝句","c":["擒虎谁探虎穴中，分明敢入不居功。","将军负弩称前导，扫雪开门拜相公。"]},{"t":"李愬雪夜入蔡州四首 其四","f":"七言绝句","c":["参赞纶扉属秉衡，何须内主诉分明。","他年远走蓝关雪，多为碑词有不平。"]},{"t":"苏武牧羊 其一","f":"七言绝句","c":["啮雪能回塞外春，功名难望写麒麟。","谁知羝乳成归谶，便信传书有雁臣。"]},{"t":"苏武牧羊 其二","f":"七言绝句","c":["拥旄穷海有孤臣，甘与膻群作牧人。","握手河梁成永诀，荒寒塞草不知春。"]},{"t":"岘山碑","f":"七言律诗","c":["当年缓带复轻裘，太傅登临乐此邱。","敌国推心驱二竖，名山勒字独千秋。","石头旋凯谁遗策，武库谈兵尚禀谋。","我为古人时堕泪，兰亭何必擅风流。"]},{"t":"阅江楼","f":"七言律诗","c":["高楼控引大江流，狮子山头迹尚留。","天意自分南北堑，偏安时作帝王州。","朱栏凭尽三吴盛，碧水飘来六代愁。","岂为埋金无王气，何缘诚意不如娄。"]},{"t":"黄金台","f":"七言绝句","c":["漫说君王好俊才，想来名士也贪财。","黄金霍霍终须尽，慷慨悲歌孰再来。"]},{"t":"送别佟松泉","f":"五言绝句","c":["丹桂犹留种，黄金不可求。","望君南浦尽，心事两悠悠。"]},{"t":"清明 其一","f":"七言绝句","c":["爱此清明耐晓凉，偏逢置闰较春长。","上林谁是探花手，桃李争看出棘墙。"]},{"t":"清明 其二","f":"七言绝句","c":["风风雨雨近清明，草色皇都尽锦程。","谁识矮檐春最好，隔墙曾听卖饧声。"]},{"t":"清明 其三","f":"七言绝句","c":["曾记琼林预宴年，朱樱灼灼灿华筵。","当时上巳重经过，差觉今春又占先。"]},{"t":"清明 其四","f":"七言绝句","c":["又逢蕊榜放春官，消息东风尚殢寒。","偏是热中人不觉，看花早己到长安。"]},{"t":"口占绝句一首","f":"五言绝句","c":["庭院树光重，渐知生意浓。","当风未团绿，摇落亦无从。"]},{"t":"东山纪事五言排律二十韵并呈董东堡","f":"五言古诗","c":["东山肃瞻仰，密迩式前人。","风树儿孙听，园林世代因。","身居华屋乐，心切首邱仁。","霜露常殊景，冈峦近比邻。","成功原自艮，开物必于寅。","隅对参星次，宫分木德春。","平临当绿野，高拱接苍旻。","重叠张帏幕，趋迎作主宾。","川回疑带曲，峰矗俨云屯。","势隐宫墙閟，形联指臂亲。","何须驱虎豹，聊复辟荆榛。","石笋环城郭，虹螺供海滨。","柏枝摇凤尾，松干簇龙麟。","神路溪桥引，灵泉古井新。","烟岚凝瑞霭，蔬果荐嘉珍。","应谨樵苏禁，将令雉兔驯。","閒花堆小径，短草藉晴茵。","遗令希元凯，佳城待沈彬。","青乌传已失，黄壤辨谁真。","董德章犹在，何殊郭景纯。"]},{"t":"寒月二首 其一","f":"七言绝句","c":["江楼晚眺独萧然，玉宇霜高皓魄圆。","虽是团栾能满望，嫦娥孤冷有谁怜。"]},{"t":"寒月二首 其二","f":"七言绝句","c":["云净星疏露气濡，皎然明月一轮孤。","窗前疑是霜华重，影射梅花半有无。"]},{"t":"寒林二首 其一","f":"七言绝句","c":["迢迢寒树隔前川，几处昏鸦噪暮天。","落叶尚同榆荚绿，萧疏不似买春钱。"]},{"t":"寒林二首 其二","f":"七言绝句","c":["一例秋光到远林，寒乌犹自旧巢寻。","那堪故径埋黄叶，樵子归来试独吟。"]},{"t":"寒云二首 其一","f":"七言绝句","c":["天际寒云望不真，不成峰影不鱼鳞。","故山岂是无心出，尚有登台载笔人。"]},{"t":"寒云二首 其二","f":"七言绝句","c":["寥寥天际片云横，冷淡全无作雨情。","不为寒山好依恋，人心多是爱冬晴。"]},{"t":"寒雁二首 其一","f":"七言绝句","c":["远来关塞影含霜，恐为风高偶乱行。","近得迎阳融雪爪，潇湘彭蠡水茫茫。"]},{"t":"寒雁二首 其二","f":"七言绝句","c":["寥阔江天雁影横，平沙旧印尚分明。","年年寄得霜来信，岂独冲寒诉旅情。"]},{"t":"寒钟二首 其一","f":"七言绝句","c":["睡觉西窗月影残，挑灯谁念客衾单。","疏钟动我三生听，绝似丰山应早寒。"]},{"t":"寒钟二首 其二","f":"七言绝句","c":["荒寒山寺隔重林，有客寻幽渡碧浔。","忽听上方钟动处，数声杳杳搁尘心。"]},{"t":"寒砧二首 其一","f":"七言绝句","c":["冷淡秋闺急妇功，打窗黄叶下西风。","离情无限谁堪语，试听砧声断续中。"]},{"t":"寒砧二首 其二","f":"七言绝句","c":["每为惊秋动客心，连村彻夜响寒砧。","授衣休说今年早，曾听征鸿送远音。"]},{"t":"寒夜二首 其一","f":"七言绝句","c":["中庭霜重夜沈沈，借得馀光补寸阴。","耐此清寒同素志，拥书且复拥重衾。"]},{"t":"寒夜二首 其二","f":"七言绝句","c":["孤灯如豆漏频催，欲向鸡窗展卷才。","为数更筹劳问夜，清寒宛若励吾媒。"]},{"t":"寒窗二首 其一","f":"七言绝句","c":["寒窗缩瑟未逢春，积雪都成白屋贫。","且喜素光能映字，不妨冷淡热中人。"]},{"t":"寒窗二首 其二","f":"七言绝句","c":["曾爱芸窗日影迟，三冬又复下书帷。","呵将冻笔临晴雪，可念程门夜立时。"]},{"t":"寒虫二首 其一","f":"七言绝句","c":["处处蛩声四野秋，酸吟为我助清幽。","只缘唧唧难成梦，起视明河泻欲流。"]},{"t":"寒虫二首 其二","f":"七言绝句","c":["秋声过处夜沈沈，恍听欧阳叹惜音。","岂有不平争欲语，荒寒无赖起酸吟。"]},{"t":"和答孙兰畹五言律四首 其一","f":"五言律诗","c":["昔读天台赋，知君实象贤。","金声堪继响，珠彩定惊筵。","吐凤休还笔，敲门不弃砖。","鸳针须自有，何事倩人传。"]},{"t":"和答孙兰畹五言律四首 其二","f":"五言律诗","c":["良骥嘶千里，孙阳一顾知。","同声关气类，此志许驱驰。","燕市黄金霍，秋风丹桂披。","归来问消息，侍子看花期。"]},{"t":"和答孙兰畹五言律四首 其三","f":"五言律诗","c":["吾师在何处，景仰属灵皋。","品格兼金玉，文章间雅骚。","秋宵常剪烛，春雨共持螯。","谁信沮渠逊，茫茫大海涛。"]},{"t":"和答孙兰畹五言律四首 其四","f":"五言律诗","c":["生徒已寥落，心事可胜叹。","知己复谁许，小才犹见难。","閒云思旧雨，秋气感幽兰。","翘首家山外，应多怨暑寒。"]},{"t":"游普陀山喜晤寺僧明然别后却寄","f":"七言古诗","c":["兰畹向我称明然，濡笔磨墨述诗篇。","推敲字句费辛苦，此中有人山之颠。","入山已无台阁气，出世那复烟火味。","有时拈韵疏性灵，清高淡远自矜贵。","今见明然俨寒酸，慈悲欢喜兼庄严。","手持唐诗三百首，权当贝叶翻经看。","古来名僧如名士，不学戒律不衫履。","文法但可拘俗人，何必蜂子钻窗纸。","诗笔生成瞿昙花，诗才淘尽恒河沙。","说法能得无上乘，偏袒吟肩拖袈裟。","昌黎辟佛友大颠，欧阳钜儒交秘演。","访僧兼欲访名山，俱可随缘作消遣。","我当三度朝普陀，友生陪侍来游歌。","清静自得古欢趣，开轩高挹秋风多。","临风且咏将进酒，有约不来良辰负。","佛国极乐重行行，石火流光莫回首。","可念前人曾志游，题诗不惜姓名留。","天末鸿雁尚流影，肯让崔题黄鹤楼。"]},{"t":"题画二首 其一","f":"古风","c":["有山无水树光燥，有水无山泽气多。","安得依山尤近水，阴阳匀配相冲和。","花掩映，树遮罗。","有时罢读且释卷，有时垂钓不披蓑。","荒苔落叶无人迹，一声款乃轻舟过。","远山澹沱入烟雾，远水迷离生烟波。","吁嗟乎邯郸梦好易反覆，长安道阻多蹉跎。","世间佳境亦尽有，此心不动奈我何。"]},{"t":"题画二首 其二","f":"楚辞体","c":["买画值一纸，买山需万钱。","将山写入画，遂令抵万千。","吾郡韩公妙山水，同学弟子罕比肩。","大米小米擅双绝，顷刻泼墨生云烟。","今得残绢胜拱璧，神妙宛尔秋毫颠。","山无皴兮生茂树，水无波兮来远船。","茅屋数楹隐深处，恰有人焉临窗前。","我笑达摩面壁立，恨不置身画中天。","吁嗟乎张繇龙曹霸马，小技皆有入神者。","阳春白雪郢中歌，其曲弥高其和寡。"]},{"t":"庚辰恭读仁宗大行皇帝七月二十五日遗诏谨纪","f":"五言古诗","c":["高庙倦勤日，先皇御极年。","寅清开宝历，申命绍心传。","骏烈销兵革，鸿文范简编。","箴言悬吏镜，科律应薰弦。","疏导河源活，澄明海气鲜。","丰镐勤再幸，岳渎表孤虔。","番舶遥修贡，民瘝屡沛蠲。","尊亲同血气，化育溥渊泉。","讵意成功退，乃闻遗诏宣。","旌旗空想像，弓鼎莫攀缘。","云拥苍梧驾，风高榆木川。","乌号当跸路，龙驭己宾天。","哭奠盈三辅，威灵震九边。","至尊本无外，馀泽犹广延。","昔岁明光里，微臣对越前。","桥山安可仰，涕泪亦潸然。"]},{"t":"三槐吟","f":"五言律诗","c":["昔闻王氏子，当户植三槐。","草木含灵气，儿孙列上台。","吾家先大父，手泽毓嘉材。","此后花黄候，长安孰往回。"]},{"t":"咏雪","f":"七言律诗","c":["分明飞絮小阳春，又似天花落世尘。","来岁祈年应贵玉，深宵望气已成银。","粉妆无处不称艳，白屋谁家可送贫。","亦有严寒全未觉，浅斟低唱属何人。"]},{"t":"书怀诗","f":"五言律诗","c":["天地自空阔，风云无尽期。","春华冒寒发，野马相息吹。","人事终成故，生机日出奇。","将来难略处，妙在不能知。"]},{"t":"题程小泉先生画册","f":"五言古诗","c":["昔我立程门，雪吹三尺积。","挥麈细论文，临池学作字。","亦或试涂鸦，笔墨聊游戏。","吁嗟二十年，风流成往事。","片纸寄精神，恍惚闻謦欬。","展卷托长言，用以鸣相思。"]},{"t":"题画二首 其一","f":"五言古诗","c":["种花复种蔬，色香乃兼擅。","以之写丹青，生气更葱茜。","此笔能双行，如上宣和殿。","此味可自知，莫上苍生面。","小技虽雕虫，绘事悟后绚。","试开绿野堂，懒作河阳县。"]},{"t":"题画二首 其二","f":"古风","c":["丹鼎在人身，本来无别具。","神仙不可求，况被黄金误。","此老一何贪，坐看丹九度。","壶中日月长，但见悬双瓠。","我欲借此鼎，用之调盐梅。","宁知既未济，火候须疑猜。","君火耶、相火耶、文火耶、武火耶，三昧不传之火耶。"]},{"t":"和镇国公宗室晋戬斋姜女祠诗一首","f":"七言律诗","c":["洪涛万顷隔燕齐，尚见神山旧女祠。","青冢与谁分怨恨，普陀何地不慈悲。","至尊临幸犹凭吊，千载传闻每异辞。","应是望夫身化石，莫将环佩感来迟。"]},{"t":"和瑞芝厓奉使朝鲜抚宁道中偶成元韵","f":"七言绝句","c":["山光海气漾云容，恰好春耕卜岁丰。","天为行人作方便，晚晴遥见夕阳红。"]},{"t":"咏选图六首 其一","f":"七言绝句","c":["人情到底尚圆通，识得行藏在个中。","太极未分含造化，混元运物有天工。"]},{"t":"咏选图六首 其二","f":"七言绝句","c":["灿如星宿各分躔，迟速高低尽左旋。","除是太阳行度远，那能一日一周天。"]},{"t":"咏选图六首 其三","f":"七言绝句","c":["当年团拜到金台，首选于今有郭隗。","可惜大罗天上客，谪来也许入轮回。"]},{"t":"咏选图六首 其四","f":"七言绝句","c":["难得仙成九转丹，循环恰比走晶盘。","无端化出重规样，当作联珠合璧看。"]},{"t":"咏选图六首 其五","f":"七言绝句","c":["遁甲禽壬老将精，军行圆阵取环生。","攻城必缺难泥古，转类开门召外兵。"]},{"t":"咏选图六首 其六","f":"七言绝句","c":["千人顶上共圆光，胜地初开选佛场。","此是涅盘能度众，机关全在转轮王。"]},{"t":"赠冀翁","f":"七言绝句","c":["不到家山二十春，康强又度古稀旬。","怕因乡饮推三老，认作当年绛县人。"]},{"t":"和沈香馀原韵","f":"七言律诗","c":["春风杨柳满章台，定识君诗见别裁。","芳草有情偏有恨，野鸥无事亦无猜。","谁怜伏骥堪长策，难薄雕虫是小才。","记否当年来月下，秋阶联句共徘徊。"]},{"t":"都中怀梅澥一首","f":"七言律诗","c":["少年荣宦老康宁，也是人间福寿星。","俗事何妨作消遣，伤心多半费调停。","长安西望人偏远，春色东来草又青。","欲把怀思相慰藉，恐劳情绪不堪听。"]},{"t":"闻立亭言梅澥寄书问都中诸友音耗感而赋此","f":"七言律诗","c":["京邸驰书问友朋，老人离索想难胜。","德星称瑞宁常聚，尺蠖求伸竟后兴。","新雨挑灯虚五夜，故山回首隔千层。","遥遥幸有知音在，尚拟携琴受广陵。"]},{"t":"挽同年何愚溪一首","f":"七言律诗","c":["到门投刺忽惊心，往事风流不可寻。","莺树乍迁春已暮，鸾弦重续韵偏沈。","新知悃款神相契，旧仆殷勤酒更斟。","犹有遗孤成似续，传家何必满籯金。"]},{"t":"红叶四首 其一","f":"七言律诗","c":["感怀聊作慰怀诗，况复秋光动客思。","种树那能逢火齐，看山从未到焉支。","赤城霞起仙居远，紫塞云深雁影迟。","记得年年芳草绿，王孙何日是归期。"]},{"t":"红叶四首 其二","f":"七言律诗","c":["一夜西风万壑声，刁条寒树焕新荣。","红楼三面迷花径，紫陌千章近帝城。","绚烂不嫌秋意老，暄妍犹带夕阳明。","休誇似锦争春色，那识孤松盖已擎。"]},{"t":"红叶四首 其三","f":"七言律诗","c":["墙阴老绿渐婆娑，瑟瑟西风动远柯。","红杏醉醒芳草地，绛霜飞断洞庭波。","珊瑚成树终能朽，锦字题笺竟不磨。","莫道昨宵霜意重，杜鹃啼血五更多。"]},{"t":"红叶四首 其四","f":"七言律诗","c":["萧萧寒树水潾潾，摇落深秋叶尚新。","到海定知来赤县，随风应不作红尘。","林端衬出千山翠，夕照看成二月春。","曾忆送人南浦绿，一番回首一伤神。"]},{"t":"题惠远禅师小照 其一","f":"七言绝句","c":["禅罢慵开选佛场，披襟露坐起微凉。","不须咒海成菡萏，自有莲花似六郎。"]},{"t":"题惠远禅师小照 其二","f":"七言绝句","c":["清修何事上团蒲，小坐花间手念珠。","侍者不知香色戒，从旁虔奉淡巴姑。"]},{"t":"题惠远禅师小照 其三","f":"七言绝句","c":["恰是当年惠远师，虎溪微笑客归时。","花前尚有樽中酒，应是知交又订期。"]},{"t":"题惠远禅师小照 其四","f":"七言绝句","c":["莞尔何因自解颜，幸朝南海落伽山。","非从紫竹林中过，那得携来玉笋斑。"]},{"t":"题惠远禅师小照 其五","f":"七言绝句","c":["莫将泥絮比禅家，泥絮含春又长芽。","香树尽能招玉凤，为他还作牡丹花。"]},{"t":"题惠远禅师小照 其六","f":"七言绝句","c":["无碍庄严法界开，诸天欢喜见如来。","分明瓶柳垂甘露，又度人间小善才。"]},{"t":"慰人下第一首","f":"七言律诗","c":["尽将文字判升沈，消息于今莫可寻。","谩说妍媸无定品，怎从难易见传心。","黄花晚节能争秀，白雪高歌孰赏音。","渺渺前程何处觅，千岩万壑各晴阴。"]},{"t":"十二月看牡丹 其一","f":"七言绝句","c":["牡丹偏欲傲梅枝，富贵争先恰出奇。","何似春深三四月，天时人事两相宜。"]},{"t":"十二月看牡丹 其二","f":"七言绝句","c":["可惜名花睡未醒，被人强起逗春情。","重帏密室深深护，不恨东风是此生。"]},{"t":"十二月看牡丹 其三","f":"七言绝句","c":["无奈冲寒放牡丹，勉成富贵亦非难。","此番出世休疑早，只为旁人带笑看。"]},{"t":"十二月看牡丹 其四","f":"七言绝句","c":["国色当前秀可餐，争妍应不怕春寒。","捲帘休惜胭脂冷，燕赵佳人本耐寒。"]},{"t":"十二月看牡丹 其五","f":"七言绝句","c":["缇室才吹六管灰，蓦然生意牡丹开。","春风欲启东皇驾，先遣天香导引来。"]},{"t":"十二月看牡丹 其六","f":"七言绝句","c":["花事能回隔岁春，冬烘倍觉长精神。","终须富贵趋炎热，知否旁多冷眼人。"]},{"t":"思亲一首","f":"五言绝句","c":["绝裾情已忍，捧檄意何欣。","回首家山远，英英有白云。"]},{"t":"除夕一首","f":"五言绝句","c":["客景逢除夕，无聊转厌喧。","遥知北堂上，焚烛看花繁。"]},{"t":"都中喜晤同年时两峰","f":"五言律诗","c":["朝廷设科目，奔走天下材。","万里金门近，三春蕊榜开。","文章争气运，饥渴慰朋来。","已识徵车到，奎垣耀上台。"]},{"t":"白丁香 其一","f":"七言绝句","c":["香雪团团压碧枝，东风吹不落阶墀。","去年梅信休言早，寒素逢春也未迟。"]},{"t":"白丁香 其二","f":"七言绝句","c":["簇簇新鲜结蕊圆，香凝素质向春暄。","有时斜荫青榆影，一斛珍珠万贯钱。"]},{"t":"紫丁香 其一","f":"七言绝句","c":["谁家墙畔数枝斜，疑是新晴落绛霞。","今日早朝趋紫陌，花光何处不繁华。"]},{"t":"紫丁香 其二","f":"七言绝句","c":["春色鲜于二月中，分明姹紫胜嫣红。","翻疑误泼胭脂水，化出花身迥不同。"]},{"t":"游丰台","f":"七言律诗","c":["南西门外竞繁华，春社游人半走车。","多少墓田依井臼，休从花县问桑麻。","秧歌终觉少年好，香会转因晴日赊。","更喜村家小儿女，新衣楚楚隔篱笆。"]},{"t":"纸鸢二首 其一","f":"五言律诗","c":["全借吹嘘力，东风太有情。","入云明夕照，出谷避新莺。","奋迹疑无碍，淩虚势欲鸣。","何须传雁帛，片纸度重城。"]},{"t":"纸鸢二首 其二","f":"五言律诗","c":["点缀三春景，儿童愿不违。","游丝飘漠漠，片纸去依依。","映日鸾翔举，迎风鹢退飞。","高楼凝望处，极目到斜晖。"]},{"t":"都中喜晤宝山侄携眷自蜀归省并应顺天乡试二首 其一","f":"五言律诗","c":["万里尝辛苦，高堂尚倚门。","白云何处远，青眼几人存。","迈迹昌宗祏，观光近帝阍。","嗟予犹碌碌，十载事鸡豚。"]},{"t":"都中喜晤宝山侄携眷自蜀归省并应顺天乡试二首 其二","f":"五言律诗","c":["谋生计不就，决策思长征。","双剑倚天表，五丁严客程。","丝萝原有定，卵翼竟何成。","莫说他乡好，家山亦锦城。"]},{"t":"出城篇","f":"五言古诗","c":["出城见禾黍，精神渐已旺。","附都百万家，食指庶堪望。","东南事转输，储需众企仰。","齿繁地不辟，矧可游手旷。","念此力田农，妇子勤馌饷。","炙肤当炎熇，没骭被新涨。","颗粒易金钱，宁有富贵想。","富贵须生成，岂能人力创。","一食中人产，一衣百宝装。","踏青油幕车，问夜销金帐。","瓜果荐冰槃，焚香合郁鬯。","那知终岁勤，仅堪出入量。","风雨不从人，灾祲转多恙。","歉收少盖藏，所幸免寇攘。","乃者官符下，老幼生惆怅。","西邻有逃亡，问尔胡不防。","东邻有杀牛，问尔胡未访。","株累经旬月，不能达一状。","堂上养威严，但愿速加杖。","黄口尚待哺，残喘泣相向。","安得念民艰，尽如太守况。"]},{"t":"嘲庶常散馆压班外用 其一","f":"七言绝句","c":["蓦地风生响玉珂，难将豹变语同科。","诸君定作循良吏，到处先传虎渡河。"]},{"t":"嘲庶常散馆压班外用 其二","f":"七言绝句","c":["入世吟成猛虎行，我今履尾亦心惊。","愿无苛政伤民隐，白额南山患自平。"]},{"t":"为冀老嘱题 其一","f":"七言绝句","c":["老去消除躁气多，几将炎热静中过。","清风颇有故人意，爱我时来安乐窝。"]},{"t":"为冀老嘱题 其二","f":"七言绝句","c":["当年度木到深山，亦识名材遇合艰。","今幸一枝栖处稳，不劳千里费跻攀。"]},{"t":"为冀老嘱题 其三","f":"七言绝句","c":["益寿何须参与苓，年来已自鬓星星。","养生非欲辞甘苦，世味酸咸我已经。"]},{"t":"为冀老嘱题 其四","f":"七言绝句","c":["壮怀迟暮复何求，人世沧桑七十秋。","闻道诸孙尽林立，拟将祝寿点牙筹。"]},{"t":"五塔寺","f":"五言律诗","c":["五岳真形具，崔巍踞法台。","石门时启闭，磴道喑纡回。","风铎层层系，金身面面开。","遥知官路外，瞻仰万人来。"]},{"t":"万寿寺","f":"五言律诗","c":["兰若附京邑，戒坛生静机。","六尘谁度脱，三宝众归依。","海外旃檀供，阶前洞壑微。","曾闻诸佛祖，遗像此传衣。"]},{"t":"昆明湖","f":"五言律诗","c":["望洋成巨浸，疏导各分流。","润泽滋香稻，澄清出御沟。","微风生水榭，倒影控山楼。","圣世无征战，沿堤有钓舟。"]},{"t":"西顶","f":"五言律诗","c":["四月朝西顶，纷如百戏陈。","喧阗疑鼎沸，车马若云屯。","隔院闻钟磬，连楹拜鬼神。","年年春社好，盛世每经旬。"]},{"t":"同冀翁游小有馀坊和题壁原韵","f":"五言律诗","c":["采取西湖胜，居然小有天。","沿堤窥扇影，隔树漾茶烟。","辞阙知何日，离家忆去年。","纵游休荡意，在坐有宾贤。"]},{"t":"附原诗","f":"五言律诗","c":["小坐耽幽趣，乡心接远天。","村光浓树色，篱影隔溪烟。","鸿爪曾羁客，莺花说绮年。","浇愁惟有酒，差幸主人贤。"]},{"t":"挽石绮园二首 其一","f":"七言律诗","c":["廿年声气亦前因，少小相从长益亲。","岂料君今为异物，再攻吾短属何人。","驰驱千里言犹在，抛却双雏志未申。","那可故斋重过访，萧萧竹影独伤神。"]},{"t":"挽石绮园二首 其二","f":"七言律诗","c":["休誇大志薄求田，聊为谋生事偶然。","云路有心皆幻想，风波无意亦经年。","双鱼已渺三春约，一病长成万古眠。","此后谁论恩与怨，离离冢草羃秋烟。"]},{"t":"述往","f":"七言古诗","c":["人道长安作客难，米珠薪桂生计艰。","我来今已再寒暑，饔飧聊复供盘餐。","忆自去年夏四月，僦居矮屋耐炎暍。","久旱忽逢大雨行，那堪怪事叹咄咄。","温风不止雨不休，积成沴气纷四流。","始自闽粤渐江北，继遍齐鲁盈中州。","况乃京师五方处，袂云汗雨称繁庶。","讹言市虎贤智惊，遂令当食愁举箸。","须臾哭声沸西邻，又见东家悲死人。","吊唁相顾少颜色，一日再见尤相亲。","沈阴积湿益泥泞，空阶夜滴何堪听。","老屋崩颓作远声，铜山西倾洛钟应。","是时燕台置黄金，诸生云集贲来临。","初作攀龙附凤想，旋成乞骨归田心。","忧疑幻起杯蛇影，心恻寒泉占幕井。","养生学得不彻姜，邵平空种瓜千顷。","络绎丧车填巷衢，尚有骼胔傍城隅。","饬令门尉藉明数，经旬累月终模糊。","延医传方不问状，延僧先期后不让。","彻夜置椑难给求，转恨择术未为匠。","震地轰闻万爆声，金吾惊起夜登城。","宁干禁令驱疠鬼，谁为戎首难知名。","飒然八月秋风迅，出门始觉精神振。","吾侪今是过来人，家书常报平安信。"]},{"t":"喜晴","f":"五言律诗","c":["花阶生爽气，向夕得晴天。","满月如新沐，归云若凯旋。","名微消物议，身健少愁牵。","徙倚纱窗下，推敲抚旧篇。"]},{"t":"同年周松崖将赴粤西荔浦任招诸同年集陶然亭小饮书此赠别","f":"七言律诗","c":["同领春风十载前，几人今此醉陶然。","历官各有升沈感，问岁均非少小年。","城阙秋生思远道，楼台夕照入华筵。","荔江一勺清如许，又得莲溪万斛泉。"]},{"t":"十二月初二日以签掣四川引见乾清宫","f":"七言律诗","c":["金殿朝开彻曙光，当年曾此对先皇。","两朝诣阙仍书腐，十载弹冠尚御香。","捧檄拟经筹笔驿，观风许过浣花堂。","遥知望斗京华远，且听流莺绕建章。"]},{"t":"出都","f":"五言律诗","c":["需次来都下，淹留两度秋。","半生初发轫，万事费持筹。","长路辞残岁，高堂重远游。","腐儒何裨用，投笔亦封侯。"]},{"t":"游子吟题别山壁","f":"楚辞体","c":["别山之阳，村树茫茫。","心之忧矣，惄然神伤。","别山之阴，村树沈沈。","永怀不见，实劳我心。","山之灵兮若有知，游子思归兮安可期。","蜀道难兮前路遐，倚门闾兮天之涯。"]},{"t":"谒杨椒山先生祠","f":"七言律诗","c":["昔年展卷瞻遗像，今日停车谒旧祠。","有命不因廷杖死，无人敢向逆鳞披。","左迁再起心逾壮，遗嘱千言我亦悲。","宿望诸公空袖手，欷歔碑记又何为。"]},{"t":"邯郸道上","f":"五言律诗","c":["有生皆有死，造化实为之。","富贵无恒势，穷愁有尽期。","长生何所济，游戏亦非宜。","且饱黄粱饭，卢生未足奇。"]},{"t":"过汤阴谒岳忠武祠","f":"七言律诗","c":["建牙曾欲荡膻腥，想见孤忠汗简青。","附会竟成三字狱，偏安甘作小朝廷。","龙沙略敌传奇迹，虎帐谈兵废武经。","宋代江山何处是，崇祠故里妥英灵。"]},{"t":"河南道上","f":"七言绝句","c":["北条陵麓发云中，与我家山支派同。","一路随车作迎送，临河凝望已回东。"]},{"t":"过东汉孝子郭巨故里","f":"五言古诗","c":["杀妻可求将，要君乃烹子。","其中热功名，流弊至如此。","异哉汉郭巨，养母埋婴儿。","饼金荷天赐，显著姓名奇。","饭牛藏腹帛，撒粒招群乌。","俶诡标奇节，遂致成矫诬。","嗟彼中庸行，菽水足欢娱。"]},{"t":"函谷关","f":"五言律诗","c":["城小凭山固，雄师困仰攻。","兴衰看启闭，疆界限西东。","关尹占佳气，甘卿表閟宫。","湍流飞瀑处，势与建瓴同。"]},{"t":"华阴庙观秦槐汉柏歌","f":"古风","c":["华阴道上麦齐肩，华阴庙中树参天。","阴森但觉四月冷，幽冥气象生万千。","楼台高出树杪上，登楼适当三峰巅。","道士导予穿树出，秦槐汉柏当阶前。","更有商周旧时树，横陈又出秦汉先。","何况唐宋后植物，低伏仅可称曾玄。","吁嗟乎秦皇汉武求神仙，何如此槐此柏能延年。"]},{"t":"马嵬","f":"七言绝句","c":["未必行军气不扬，姜妃走马定岐梁。","情深别有兴亡感，千载明皇与太王。"]},{"t":"五丈原","f":"五言绝句","c":["筹策南方定，中原尚可为。","出师再陈表，涕泣已长辞。"]},{"t":"宝鸡入栈","f":"五言律诗","c":["一径通川蜀，连山限楚秦。","翻疑去无路，且喜来有人。","灯火明林表，驮駖响涧滨。","伏波能聚米，恐此是陈因。"]},{"t":"鸡头关","f":"五言律诗","c":["几日辞车马，山行已惯经。","云关殊气候，神庙仰威灵。","路转周天度，江流匹练形。","褒斜回望处，万岭锁空青。"]},{"t":"沔县谒武侯祠见铜石二琴","f":"五言律诗","c":["清越弹丝异，声流石与金。","英灵无朽质，劳瘁尚鸣琴。","第宅留天府，山邱望沔阴。","从来师相重，谨慎是传心。"]},{"t":"邛州道上望黎雅诸山","f":"七言律诗","c":["已离云栈十馀程，又见高山天外横。","苍碧凝阴疑岳秩，青冥含气幸时清。","壮年如我犹堪学，远宦伊谁不为名。","亦识升沈难预定，成都何处访君平。"]},{"t":"荣经署中","f":"七言律诗","c":["专城百里辟蚕丛，叱驭名贤此教忠。","郭外溪声喧暮雨，堂前山色引薰风。","南人不忍欺诸葛，文帝何能富邓通。","四十年来甘澹泊，而今故我复飘蓬。"]},{"t":"相岭","f":"七言律诗","c":["坤维盘错百千层，相岭岧峣试陟登。","四月峨嵋看积雪，三更瓦屋见神灯。","平铺云气尘寰远，屈折山蹊古迹仍。","况是武侯经过处，即今祠宇想依凭。"]},{"t":"署中杂兴","f":"七言律诗","c":["云栈萦纡历轗轲，精神到此已销磨。","芭蕉苦雨心常卷，鹦鹉樊笼语不多。","无事藉眠消昼永，摊书善忘感时过。","何年再共家山乐，戏看牛羊下夕坡。"]},{"t":"咏太湖寺石","f":"七言古诗","c":["曾闻西湖天竺寺，昔年传有飞来峰。","削拔特起无倚附，玲珑瑰异称鬼工。","此石不与众石伍，负奇蕴秀深山中。","万牛牵挽不能到，安排那可人力通。","娲皇补天有遗物，岿然坐镇山门东。","佛法无边莫思议，擘分灵鹫开蚕丛。","严壑幽邃具生气，阴阳向背盘虚空。","重叠纡回势合沓，小山尤为大山宫。","其下端平委入土，措置有情疑天公。","襄阳米老具石癖，阿兄定宜称谓崇。","我今竟欲呼为丈，县令难与太守同。"]},{"t":"梓潼宫","f":"五言律诗","c":["神灵炳天下，庙祀故乡多。","遗像存生气，明星应制科。","化身经世宙，流泽汇江河。","绿竹通幽处，还同七曲坡。"]},{"t":"安澜寺","f":"五言律诗","c":["江边孤寺在，保障固金城。","巨石鱼鳞集，长堤雉堞平。","虽资民力助，何惜宦囊倾。","无限临流意，三秋乐有成。"]},{"t":"白云观","f":"五言律诗","c":["参禅参佛祖，宗乘越诸天。","晨起朝莲座，斋馀穫稻田。","白云飞岭外，丛桂近窗前。","到此逢僧话，惭予逊昔贤。"]},{"t":"严道篇","f":"五言古诗","c":["自我来严道，悠悠已易年。","土风能渐悉，治理未精研。","此境当冲邑，无时不畏天。","疲繁虽暂济，凋敝尚如前。","署有栽花地，囊空饮马钱。","舂粮无隔宿，货贝少流泉。","官苦终思去，民穷实可怜。","山溪馀瘠土，风雨薄良田。","终岁餐芋麦，谋生任臂肩。","文风供笔墨，商力困铜铅。","易市童妪集，携赀子母权。","绅衿参典吏，户口匿粮烟。","翻恨流民夥，能令旧俗湮。","多财争入赘，新寡互垂涎。","为后将亲背，招夫以贿迁。","不知分族类，奚自辨媸妍。","所习原偷薄，其情乃吝悭。","锱铢甘刃蹈，睚眦竟躯捐。","弱肉资强食，锄根复蔓延。","多方勤诰诫，何计策安全。","德教殊滋愧，刑求讵足贤。","迂儒无实用，循吏不多传。","但望消尤怨，先期免过愆。","升沈焉有定，出处岂徒然。","云气溶溶聚，江声滚滚连。","家山千万里，飞梦过幽燕。"]},{"t":"双柏行","f":"古风","c":["边城废兴关治乱，山河代易形势殊。","乔木亭亭表故国，前人手泽留规模。","堂前老柏双蔚起，参天黛色霜露濡。","左进右退若相逊，盘崛天矫分荣枯。","龙翔凤翥作奇态，阴森尚疑神护扶。","古物历劫聚精爽，四邑休咎占适符。","民命至重天听近，树杪厌闻朝啼乌。","君不见西台御史持明法，三槐九棘无滥竽。","又不见殷人尚鬼留社木，先罚后赏民自孚。","吁嗟乎，武侯治蜀功不朽，于今祠树犹旁敷。"]},{"t":"古樵郭明府甫卸雅篆又权芦山别未及月作再来人喜而赋寄 其一","f":"七言律诗","c":["何必痴聋作阿翁，君今更达四门聪。","重看西土劳郇伯，却向东邻借寇公。","前度去思寻旧雨，故人来惠比清风。","昨朝封柬勤邮使，竟与催官符箓同。"]},{"t":"古樵郭明府甫卸雅篆又权芦山别未及月作再来人喜而赋寄 其二","f":"七言律诗","c":["小熙春馆敞离筵，泥爪新痕尚宛然。","鸿雁依群冲雪至，卿云辞岫被风还。","重经花县犹今我，无事琴堂亦散仙。","闻道君家有金穴，可能资助邓通钱。"]},{"t":"和古樵郭明府见寄原韵 其一","f":"七言律诗","c":["依恋慈云去住身，宦游何处不劳人。","栽花且采灵关药，载酒重寻丙穴鳞。","三辅河东曾假郡，半旬京兆又移邻。","笑君却似南飞雁，有意迟来作后宾。"]},{"t":"和古樵郭明府见寄原韵 其二","f":"七言律诗","c":["羡君说法现全身，也是胪传第一人。","鹏路高骞难比翼，龙门近接欲攀鳞。","临江鞭影辞千里，还浦珠光照四邻。","恰似行文无定格，有时移主可为宾。"]},{"t":"自遣","f":"五言律诗","c":["揽镜髭须异，高堂亦可知。","显扬难慰老，成就易惊迟。","佳境期儿辈，韶光忆少时。","坤爻初画意，造化究何私。"]},{"t":"答汪桂山明府和古樵寄作仍依韵续成六首 其一","f":"七言律诗","c":["自笑因官重累身，甘将能事让他人。","敢誇猿臂穿蹲甲，怕探骊珠触逆鳞。","觞政不堪依酒国，弦歌真欲托诗邻。","年时雅雨堂前宴，且看于今孰主宾。"]},{"t":"答汪桂山明府和古樵寄作仍依韵续成六首 其二","f":"七言律诗","c":["维摩常示病中身，博得公馀作倦人。","珍重刀圭驱二竖，殷勤尺素遗双鳞。","关心严道难成宦，翘首名山欲卜邻。","最好灵关新聚会，羡他贤主更嘉宾。"]},{"t":"答汪桂山明府和古樵寄作仍依韵续成六首 其三","f":"七言律诗","c":["仙班领袖是前身，应向芦中唤若人。","薄霭烘霞成蜀锦，寒云笼月叠鱼鳞。","汪伦情绪深千尺，郭伋贤名藉四邻。","为解相思拈和句，拟将邮使浼龙宾。"]},{"t":"答汪桂山明府和古樵寄作仍依韵续成六首 其四","f":"七言律诗","c":["天涯万里宦游身，坐守山城一钝人。","花屿春深无倦鸟，江滩流急有惊鳞。","含愁老女为商妇，疑窃贫儿怯富邻。","回首琼林风物好，于今几见座中宾。"]},{"t":"答汪桂山明府和古樵寄作仍依韵续成六首 其五","f":"七言律诗","c":["旅宦休称自在身，艰难蜀道想前人。","初晴日色惊痴犬，新涨江流起涸鳞。","百里量才依小县，千金无价买芳邻。","迢遥北望仙关渺，可许吹箫和洞宾。"]},{"t":"答汪桂山明府和古樵寄作仍依韵续成六首 其六","f":"七言律诗","c":["云影萍踪共此身，怜才太守重诗人。","名山采取无凡卉，大壑飞腾有巨鳞。","春色遥看来北阙，馀光分照借东邻。","知君近日烹新茗，且搁残杯待远宾。"]},{"t":"除夕九叠前韵","f":"七言律诗","c":["读书期作致君身，政绩循良羡古人。","岂料出山成小草，那知烧尾尚凡鳞。","依光日下空回首，托迹天涯洽比邻。","无限乡心逢易岁，懒开官阁去延宾。"]},{"t":"四经楼怀古","f":"七言古诗","c":["依山起楼作高势，倚楼看山成远观。","四围竹树尤茂密，置身直出绿云端。","汉嘉边郡生繁众，兴衰多被长江送。","老鹳依巢不忍飞，书帷已去贤昆仲。","文章杰出高层楼，豪气奔流千古留。","魄力雄伟义正大，王氏新学生隐忧。","青苗行法天下乱，食肉无盐遭远窜。","赤壁赋成山月高，老去金莲撒御案。","谁是明达如老泉，家学渊源能辨奸。","囚首诗书已难近，何待天津闻杜鹃。"]},{"t":"过名山谒汪明府留饮别后却寄","f":"七言律诗","c":["金鸡关外放新晴，万井田畦水正盈。","编户殷繁环客路，平冈低伏入山城。","重开樽酒经三载，先导行旌过一程。","为爱君诗似春色，撩人无奈最多情。"]},{"t":"敬谒房师晓亭夫子并叩见太师母太夫人及二世兄三世兄退而志喜 其一","f":"七言绝句","c":["春深燕寝昼凝香，竟许彭宣拜后堂。","南极婺星临井络，可知爱日正舒长。"]},{"t":"敬谒房师晓亭夫子并叩见太师母太夫人及二世兄三世兄退而志喜 其二","f":"七言绝句","c":["翩翩公子擅风华，三凤齐名傲薛家。","旧植兰台已成荫，新秋犹放榜头花。"]},{"t":"敬谒房师晓亭夫子并叩见太师母太夫人及二世兄三世兄退而志喜 其三","f":"七言绝句","c":["弹章朝奏五云端，台阁风生慄不寒。","今日御屏书郡守，须知观察藉言官。"]},{"t":"敬谒房师晓亭夫子并叩见太师母太夫人及二世兄三世兄退而志喜 其四","f":"七言绝句","c":["衣钵和凝孰嗣徽，扶风绛帐两暌违。","迩来自问无贪取，只算师门具体微。"]},{"t":"答金虞臣用黄秋崖小集薛涛井原韵","f":"七言律诗","c":["溯流帆影近夔东，果否三江景略同。","客路订交缘数定，小春听雨望年丰。","山迎人面饶生趣，柳绾乡思倩好风。","遮莫边城叹岑寂，郢中白雪有元工。"]},{"t":"少府黄秋崖以薛涛井公宴旧作见示因依韵和答","f":"七言律诗","c":["水光山色拥孤城，冷淡同君一味清。","背郭尽馀调马地，倚楼欣听读书声。","偷閒行部占晴雨，解惯冲途作送迎。","春梦搅人眠未足，惊心官鼓又天明。"]},{"t":"喜雨","f":"五言律诗","c":["一雨人心定，郊原畅晓阳。","溪添春水绿，风漾菜花黄。","弦管开清宴，云山隔故乡。","相安幸无事，民气本淳良。"]},{"t":"闻古樵之任高州志别一首","f":"五言律诗","c":["一去邻滇省，山川壮宦游。","边城依岭峻，琴阁共云浮。","地比仙关渺，人经雅雨秋。","昔年刘十六，曾此作高侯。"]},{"t":"雨后","f":"五言律诗","c":["雨后滩声响，连山霁复阴。","看云作遐想，参佛生静心。","人满山溪近，堂深鼓角沈。","承平安可恃，水旱每相侵。"]},{"t":"苦雨","f":"五言律诗","c":["云气孕千山，濛濛拥阓阛。","积阴秋意早，无事宦情閒。","江势趋三峡，官途控百蛮。","雨寒民易怨，稼穑本维艰。"]},{"t":"汉嘉道上","f":"七言律诗","c":["青衣江绕蔡蒙东，疏导当年见禹功。","世治筹边能善后，山深藏疾易兴戎。","好官岂为求无事，薄命真堪解固穷。","西望崇冈千万叠，蛮疆番部每殊风。"]},{"t":"送尚声归里","f":"五言古诗","c":["瓦山高不极，积雪生春寒。","荣水逝无尽，萦波回壮澜。","儿行将万里，长路何漫漫。","临别意相喻，仰天生浩叹。","因思我父母，爱我亦多端。","髫年授我读，壮年成我官。","成全事已备，升斗谋亦殚。","既怅乡关远，奚辞蜀道难。","吁嗟宦游子，惘惘终未安。","送儿且归去，庶博堂上欢。","儿行且毋念，吾当努力餐。"]},{"t":"途中口占诗一首","f":"五言律诗","c":["火星化荧惑，厥象失光明。","太白无昼见，四方适荡平。","经天同列宿，美恶殊性情。","岂不探真宰，仰瞻终杳冥。"]},{"t":"与罗公猷","f":"五言律诗","c":["忆旧生新感，茫茫结夙缘。","英儿宁有种，穷路莫须钱。","愧乏神君誉，惭称父母怜。","因思无告者，何处少颠连。"]},{"t":"飞龙关一首","f":"五言律诗","c":["天路扪参井，飞龙擅壮名。","几番经夜雨，此日趁朝晴。","寒暑鸣禽异，崎岖古道行。","白云看不尽，流影自轻盈。"]},{"t":"示邑庶","f":"古风","c":["游民致身苦无术，坐享太平思从戎。","忽闻边警万里外，披衣起舞摩刀弓。","山邑地僻少英俊，几多呼应生长风。","何况十二郡中众，昔年乡勇未成翁。","吁嗟乎飞刍挽粟绝域远，九重筹策劳深宫，如何动色谈军功。"]},{"t":"去官 其一","f":"五言律诗","c":["祖饯劳冠盖，三年竟此辞。","江鸥浮浪远，桐叶落风迟。","几许生平愿，无多去后思。","幸当秋有穫，康阜慰心期。"]},{"t":"去官 其二","f":"五言律诗","c":["知遇未图报，抚心滋愧多。","功名方补救，人事复蹉跎。","寤寐中情结，风雷瞥眼过。","江枫吹叶下，流水自生波。"]},{"t":"去官 其三","f":"五言律诗","c":["作吏何须久，恩深怨亦深。","是非皆往迹，依恋总痴心。","仰视浮云白，回看众壑阴。","君亲奚有济，太息起悲吟。"]},{"t":"去官 其四","f":"五言律诗","c":["生我悲长诀，弥留万里天。","有儿作孤孽，无面告哀怜。","爱日徒嗟晚，奔星尚久延。","升沈何足计，忽忽已经年。"]},{"t":"奉和鲜于广文赠别元韵","f":"七言律诗","c":["别路听琴泣凤翚，荒斋苜蓿苦因依。","文章月旦推名宿，禾黍秋风稔近畿。","喜雨桥边萦绿柳，飞龙关外怅青衣。","东流似解离人意，时作回波映翠微。"]},{"t":"看云","f":"五言律诗","c":["出岫还归岫，无心亦有心。","倘令空外尽，安望复为霖。","天末片云落，层阴远势浓。","夕阳如有意，照见芙蓉峰。"]},{"t":"杜工部草堂","f":"七言律诗","c":["草堂风景足清幽，绕径寒溪静不流。","小队元戎曾见访，中唐诗卷自长留。","桂花井畔金飙冷，枫树林端玉露稠。","遗像如生微示笑，岂知当日总穷愁。"]},{"t":"诸葛武侯祠 其一","f":"七言律诗","c":["南方未定此军屯，想见英灵今尚存。","铜鼓摩挲微作响，剑门险远有归魂。","君臣一德兼师相，吴魏三分已坐论。","密迩桥山同享祀，萧萧竹影几黄昏。"]},{"t":"诸葛武侯祠 其二","f":"七言律诗","c":["古柏参天已劫焚，乔林依旧引清薰。","阵图常捍巴江水，羽扇曾挥相岭云。","祠近园陵犹顾命，身终王事竟全军。","自怜食少无生理，五丈原头怅夕曛。"]},{"t":"别余醇轩","f":"五言古诗","c":["醇轩具高节，澹泊明素风。","作吏无纤俗，交人良独忠。","清操远时誉，和蔼鸣寅衷。","两刺建南郡，恬然将固穷。","板舆亲奉养，遥隔锦城中。","锦城多甲第，君乃半亩宫。","湫隘不容驷，北堂春融融。","子弟多良善，昆季无异同。","显扬正难量，家运当盛隆。","卿霭聚嘉气，茂兰成广丛。","芳馨共相惜，结想情与通。","天末商飙至，翩然飞长鸿。","远音起哀唳，群类各西东。","闽海警氛恶，玉关方诘戎。","稻粱不谋饱，枫叶子规红。","长途叹雨雪，严冱蛰寒虫。","讵知滇池外，遗鹤鸣寥空。"]},{"t":"忆旧八首 其一","f":"五言律诗","c":["吾慕吴音木，学问擅名宿。","族望世江南，诗馀勤案牍。","戟辕清昼长，莲幕秋风肃。","相见复何时，遗函检行簏。"]},{"t":"忆旧八首 其二","f":"五言律诗","c":["吾慕魏阶平，为人忠且诚。","论文备今古，琢句含精英。","焦尾琴堪听，磨云月更明。","前途良未艾，何以老诸生。"]},{"t":"忆旧八首 其三","f":"五言律诗","c":["吾慕郭镜我，艺文均当可。","丰标绝俗尘，庶事无丛脞。","国手出楸枰，婆心勤药裹。","诗坛偶一来，列帜甘虚左。"]},{"t":"忆旧八首 其四","f":"五言律诗","c":["吾慕陈梅岑，春华努力深。","文章消宦气，诗句杂仙心。","骏誉鹏抟海，蜚声鹤在阴。","四经留旧迹，遗线尚堪寻。"]},{"t":"忆旧八首 其五","f":"五言律诗","c":["吾慕汪桂山，英风非等閒。","开樽酒无量，脱稿诗不删。","珊网登遗宝，蒲鞭警庶顽。","会须膺上荐，翘首列仙班。"]},{"t":"忆旧八首 其六","f":"五言律诗","c":["吾慕李约亭，老吏著芳型。","论事有先见，立言持正经。","金银清夜气，仁寿出祥刑。","几忆亲甘苦，居然两鬓星。"]},{"t":"忆旧八首 其七","f":"五言律诗","c":["吾慕郭古樵，才思若涌潮。","所居皆福地，一去杳云霄。","鱼柬新诗寄，芦关旧雨遥。","诗牌遗法在，几度共相招。"]},{"t":"忆旧八首 其八","f":"五言律诗","c":["吾慕章纫香，英华独擅场。","砚田无歉薄，腹笥见缥缃。","既探申韩秘，尤争李杜长。","得朋良足乐，相忆复相望。"]},{"t":"留别李约亭明府","f":"楚辞体","c":["宦游惟君久，几经沧与桑。","治乱若流水，升沈难等量。","亦或郁烦恼，亦或欢衷肠。","亦或安偃息，亦或食未遑。","黔黎殷爱戴，量移来南方。","青衣一带水，借润周四旁。","榷木众以利，君来成浮梁。","岂不擅明察，宽大实所长。","岂不念终窘，仁厚实中藏。","家既因官累，乃复空宦囊。","郭氏旧金穴，无如寝邱良。","我作严道吏，频登雅雨堂。","石麓但交臂，古樵远相望。","惟君处稍久，弹指历三霜。","肝胆气相许，芝兰香共芳。","为我理疑狱，为我监盘仓。","濒行锡我赆，促我治归装。","我行勿复念，望君日康彊。","茀禄益纯固，晢嗣隆且昌。","方今重西事，徵调及邻疆。","筹饷县官急，输运出河湟。","尤恐浮动众，乘虚作鸱张。","所赖上苍佑，今岁获丰穰。","目前既难恃，居安讵可常。","我去君且住，旧游奚自忘。","薄宦等閒事，固穷应惯尝。","独念君亲重，图报终茫茫。","呜呼知我兮爱我，心结兮心伤。","悽怆兮前路，迢递兮故乡。","江流兮日远，木落兮天凉。","永怀兮不寐，怅别兮何方。"]},{"t":"青羊宫","f":"七言绝句","c":["藏梅珍玩属何王，古质斑斓色泽光。","怪道金羊当鬼宿，积尸馀气闇文昌。"]},{"t":"支机石","f":"七言绝句","c":["想是娲皇炼未成，相随织女下昆明。","自从此石来天上，博得西川作锦城。"]},{"t":"天涯石","f":"五言绝句","c":["天涯高且远，顽石擅其名。","何处天涯是，人间无尽程。"]},{"t":"剑阁用唐刻原韵","f":"五言律诗","c":["万山送行客，客行山意回。","连朝朔风发，积阴忽已开。","长路间寒暑，悠悠思往来。","山灵讵无意，几见济时才。"]},{"t":"七盘关","f":"七言绝句","c":["南栈崎岖路不平，小心移步记分明。","今朝已过西川境，从此宽怀放胆行。"]},{"t":"伏波将军庙","f":"七言绝句","c":["戚畹能将阃外安，轻装薏苡载归鞍。","即今遗庙存封守，竟作云台画里看。"]},{"t":"紫柏山留侯祠","f":"五言律诗","c":["旧封祠汉相，留坝想英风。","借箸师黄石，藏弓伴赤松。","洞天邻少室，云栈接秦中。","千载瞻遗像，居然处女同。"]},{"t":"和沔阳题壁怀古原韵","f":"七言律诗","c":["三分难厌蚩尤旗，赖有偏安鼎未移。","郁郁军山终赍恨，滔滔汉水永方思。","春秋大义文公笔，伊吕名贤杜老诗。","何便桓温有矜色，可能妥帖似当时。"]},{"t":"归里","f":"五言古诗","c":["风雪八千里，哀哉望里门。","河干此诀别，父子各声吞。","讵意成长逝，天高终莫扪。","呼抢叩窀穸，咫尺间晨昏。","游子有归日，灵帏空自存。","起居弗能侍，应识心意烦。","含殓弗能视，奚堪诚敬论。","弥留既旬月，绝笔犹望孙。","所赖谋身后，多资季与昆。","哀哀此中结，将冀亲梦魂。","忽若平生事，仰瞻无一言。","乃知赍长恨，劳瘁空负恩。"]},{"t":"慧麟侄出痘新愈于元旦日索诗因而赋此","f":"五言律诗","c":["履端嘉气至，綵笔写新春。","淑鸟喧阳候，高楣启后人。","远将绵嗣绪，上可慰慈亲。","呼仆添炉火，题诗赐慧麟。"]},{"t":"哀思","f":"五言律诗","c":["三月旬初九，辞亲已五年。","音容安可再，劳谕想从前。","衔索鱼终朽，当风树不眠。","故园易零落，春草几芊绵。"]},{"t":"见杏花","f":"七言绝句","c":["又见山村发杏花，春光应已遍天涯。","怯寒犹自重帏下，知道炊烟有几家。"]},{"t":"咏史 其一","f":"五言绝句","c":["秦兵起倾国，江左凯旋师。","胜败寻常事，如何两不支。"]},{"t":"咏史 其二","f":"五言绝句","c":["贫穷托冥报，富贵遗千金。","一饭成恩遇，平生感已深。"]},{"t":"戊子十月二十六日引见乾清宫","f":"七言律诗","c":["七载重来觐阙庭，金门辨色又疏星。","百忙岁月蓬壶旧，九折山溪蜀道经。","敢望微官邀特简，何期薄绩达聪听。","自维年壮犹堪试，橐笔还摹剑阁铭。"]},{"t":"与德立亭吏部","f":"七言绝句","c":["少年游艺共芳春，取次连镳只二人。","小吏两番阶下立，口含天宪羡君身。"]},{"t":"路上杂咏十首 其一","f":"五言古诗","c":["父子经长别，当时涕泪挥。","今朝门外送，垂老一慈帏。","长途行未已，秋潦复沈阴。","勺水能兴浪，可知江海深。","征衣不为薄，向晓生故凉。","莫怅西风急，吹云见太阳。","海气荒荒起，风云指顾期。","不知天地大，推测自为奇。","蜀道如天上，家山梦里逢。","平冈互低伏，风景似临邛。","新月如钩出，环弯挂远岑。","旁临星一点，似写未成心。","行年几五十，全局略将成。","一为家声计，谋生安可轻。","茹苦易于已，怜穷难所亲。","长叹复何益，况有笑谈人。","推心作交结，无自解人颐。","安得一思我，正当平旦时。","路逢诸弟子，相揖过车前。","同此长安道，回思一惘然。"]},{"t":"路上杂咏十首 黄叶二首之一 其二","f":"七言律诗","c":["阴阴丛绿衬疏黄，点缀林光妙擅场。","晚节花香终觉艳，平芜草短莫悲凉。","新愁最易催人老，薄病犹堪靓晓妆。","信识金风能度物，任他著色向秋阳。"]},{"t":"路上杂咏十首 黄叶二首之二 其三","f":"七言律诗","c":["翻疑橘柚踰淮生，秋入平林画不成。","淡抹微烟含气早，初经凉雨挹尘轻。","萧萧似有辞柯意，点点偏馀唤渡情。","鏖战西风犹未已，满披金甲护山城。"]},{"t":"路上杂咏十首 红叶四首之一 其四","f":"七言律诗","c":["夕阳山树隐隆隆，更有霜容著叶红。","仙府紫霞常映日，灵禽丹绶漫迎风。","不须载酒心如醉，却意飞花兴感同。","旧宴曲江曾赐饼，香尘绮陌正春融。"]},{"t":"路上杂咏十首 红叶四首之二 其五","f":"七言律诗","c":["西来节候近澄清，路树临风最有情。","绀碧几重深坞隐，朱殷一带夕阳晴。","声中血性秋能语，梦起酡颜醉欲醒。","我尚看花心未足，红梅只合待春明。"]},{"t":"路上杂咏十首 红叶四首之三 其六","f":"七言律诗","c":["花容二月旧时春，霜叶殷红树树新。","到眼秋光明绣陌，近畿风景识枫宸。","赐绯乍可呼卢采，服紫真能化国人。","几点燕山青未了，火云流影尚轮囷。"]},{"t":"路上杂咏十首 红叶四首之四 其七","f":"七言律诗","c":["洗却尘容玉露寒，晴光烘染上林端。","江枫向夕宜残照，墙杏争春竟误看。","未老朱颜怜晚暮，从来紫气近长安。","荆关图画分明在，写出秋心一种丹。"]},{"t":"路上杂咏十首 其八 过燕山访侯孝廉","f":"七言律诗","c":["清明才过尚馀凉，十日征尘道阻长。","山近桥陵皆拜伏，田环都邑尽康庄。","春晴草木含新润，小别知交感异乡。","见说窦家能育子，君今可得好儿郎。"]},{"t":"路上杂咏十首 其九 再过邯郸","f":"七言绝句","c":["好梦占祥噩梦禳，惊心动魄是酣乡。","何如化作飞蝴蝶，自在逍遥睡一场。"]},{"t":"路上杂咏十首 其十","f":"七言绝句","c":["四十年中顷刻殊，神仙作下睡工夫。","我家日日黄粱熟，食后酣眠一梦无。"]},{"t":"邺中怀古 其一","f":"七言绝句","c":["疑冢纷纷误子孙，西陵芳草自黄昏。","那知漳水沧桑易，竟被村童阚墓门。"]},{"t":"邺中怀古 其二","f":"七言绝句","c":["铜雀台荒霸业灰，岿然冢土邺城隈。","如今片瓦犹珍赏，谁得陈思八斗才。"]},{"t":"谒鄂王祠再叠前韵","f":"七言律诗","c":["北略征衫带血腥，燐燐塞草夜含青。","东窗有计诛名将，南渡何人问虏廷。","遗墨流传争爱惜，停车修谒又重经。","太平天下寻常事，谁向神前一乞灵。"]},{"t":"渡黄河","f":"五言古诗","c":["黄河第九曲，都门当正阳。","环拱二千里，平衍适中央。","众流既奔汇，全势趋齐梁。","金钱岁縻费，疏导兼堤防。","往年忆北上，雨雪生寒凉。","层冰蔽河下，悄然心悲伤。","今我复南渡，洪波静不扬。","含浊见本性，清流讵可常。","观澜莫由挽，易逝惊就将。","有怀缅曩代，分据各殊疆。","一水限南北，时事何抢攘。","干戈日未己，和亲难久长。","孤臣念君国，游子思故乡。","安知有后世，忧乐独中藏。","临风试慨想，倚帆见北邙。","北邙多故物，流水复茫茫。","沙洲有出没，渚禽鸣且翔。","极天望无际，初日上扶桑。"]},{"t":"过四知坊","f":"五言律诗","c":["祠墓规浑朴，千秋竟不磨。","感恩殷暮夜，矢志皎星河。","白璧原无玷，黄金孰厌多。","关西延教泽，泾水挹清波。"]},{"t":"灵皈寺","f":"七言律诗","c":["隋唐宫殿已灰尘，梵宇巍峨更几新。","图画丹青皆古艳，留题名姓尚先民。","僧规浑朴具禅意，佛相庄严成贵人。","我为钟声清入听，此来瞻礼或前因。"]},{"t":"佛手柑","f":"五言律诗","c":["莫道金身幻，黄柑具体真。","拈花应欲语，合掌恰迎人。","千手本无碍，拘挛终竟伸。","倘承仙露润，盈掬自长春。"]},{"t":"题吴省庵小照 其一","f":"七言绝句","c":["引得清光满纻罗，虬枝繁荫出高柯。","斗然风过涛声响，不似惊心宦海波。"]},{"t":"题吴省庵小照 其二","f":"七言绝句","c":["丹青别具锦心肠，位置君家妙擅场。","须识身安磐石稳，中怀坦易本平康。"]},{"t":"怀忠堂口占 其一","f":"七言绝句","c":["绕郭青山万叠来，狂澜东下势难回。","夕阳天末云峰起，恰有微风送晚雷。"]},{"t":"怀忠堂口占 其二","f":"七言绝句","c":["片云携雨过山头，似我辞家作宦游。","纵有西风吹不散，轻阴随处又勾留。"]},{"t":"留别忠州书院诸生","f":"五言古诗","c":["白鹿杳难即，碧瓜无宿根。","神灵幻俶诡，竹树易黄昏。","永怀缅曩哲，风流千载存。","江山不改色，遗泽留后昆。","琅嬛开福地，桃李植公门。","当世景先进，启心资圣言。","敦崇旧仁里，士习民所尊。","秉姿既醇朴，含气复温温。","为我歌骊曲，为我侑清樽。","欢乐得知感，富贵何足论。","忆当试京兆，几度惊神魂。","奔走藉升斗，夙心常自扪。","吁嗟尔多士，为学须本原。","忠厚载庸福，功名难畔援。","青春易凋谢，回首但寒暄。","临歧重寄语，诵诗羞素飧。"]},{"t":"答朱云岑书题后","f":"七言绝句","c":["风檐校艺日初长，燕寝凝香未底忙。","且为郊行迟命驾，有怀良友写心藏。"]},{"t":"过中江城北偶得林丛二语已一易寒暑矣今续成之","f":"七言律诗","c":["又向邯郸梦里来，迢迢驿路旧官槐。","林丛好鸟关心语，篱落秋花得意开。","怀古山川当盛世，结交声气识英才。","好音不入中郎听，祇恐焦桐是弃材。"]},{"t":"宾兴宴赋诗二首 其一","f":"七言律诗","c":["槐花争趁桂花黄，簌簌青芬拂客裳。","有子读书真乐事，看君挟策上名场。","秋风展骥嘶长路，春雨听莺到建章。","今日堂前将进酒，江南司马一称觞。"]},{"t":"宾兴宴赋诗二首 其二","f":"七言律诗","c":["从事丹铅孰后先，棘闱几度际蟾圆。","万年嘉会开恩榜，八月崇阳预庆筵。","华国文章争气运，逢时利器尚钻研。","我今伫听檐前鹊，知有佳音特地传。"]},{"t":"东阁官梅十咏补遗 其一","f":"七言绝句","c":["一度春风一度开，安排东阁号官梅。","山中高士知多少，卧雪眠云望不来。"]},{"t":"东阁官梅十咏补遗 其二","f":"七言绝句","c":["竹树阴阴羃四郊，新晴刚见远山坳。","东皇消息官衙早，几点新红出碧梢。"]},{"t":"东阁官梅十咏补遗 其三","f":"七言绝句","c":["岭上新枝好护持，春风隔岁漏花期。","恨他开在黄花后，只为争先转觉迟。"]},{"t":"东阁官梅十咏补遗 其四","f":"七言绝句","c":["清绝梅花不厌贫，因何呼作在官身。","当时竞盛开东阁，负却深山富贵春。"]},{"t":"东阁官梅十咏补遗 其五","f":"七言绝句","c":["繁华满树著春容，老干又丫欲化龙。","莫道落花情意索，摊书犹藉绿阴浓。"]},{"t":"东阁官梅十咏补遗 其六","f":"七言绝句","c":["杨花飘泊李花香，事隔隋唐已杳茫。","留得梅花东阁在，清芬犹近浣花堂。"]},{"t":"东阁官梅十咏补遗 其七","f":"七言绝句","c":["花封绣错此分符，阁外春深唤鹧鸪。","只恐梅花来问我，庭前可有落花无。"]},{"t":"东阁官梅十咏补遗 其八","f":"七言绝句","c":["花间小集绿初团，风致嫣然春未阑。","座客莫谈天宝事，美人零落易心酸。"]},{"t":"东阁官梅十咏补遗 其九","f":"七言绝句","c":["沈沈官鼓放朝衙，催报新枝第几花。","可是公堂高万里，不曾春色到邻家。"]},{"t":"东阁官梅十咏补遗 其十","f":"七言绝句","c":["风流韵事说扬州，如此梅花几世修。","想见少陵题咏处，草堂东阁各千秋。"]}]};